/**
 * Call-flow graph builder for NetSapiens.
 *
 * Ported from the Engage portal (packages/shared/src/netsapiens/callflow-graph.ts),
 * itself a port of the Python ns-route-graph project (graph_builder.py). Crawls a
 * NetSapiens domain starting from each DID and produces a directed graph of
 * call routing: DID -> answer rules -> users / auto attendants / queues /
 * voicemail / off-net / hangup.
 *
 * Two changes from Engage, both at the edges:
 *   - The crawler takes a `CallFlowClient` (the six reads it makes) instead of
 *     Engage's NetSapiens SDK. That SDK calls the NetSapiens API directly,
 *     which the platform forbids apps (its bundle check rejects the API's URL
 *     prefix outright); ./client.ts makes the six reads through the host API
 *     proxy instead.
 *   - A node's `link` names the Virtual Switchboard panel it opens (user or
 *     queue), not an Engage page (see nodeLink below).
 * Everything else (the walk, the time simulator, the filters) is unchanged, so
 * the two tools draw the same graph for the same domain.
 */

/**
 * The NetSapiens reads the crawler makes. Shaped like the Engage SDK resources
 * it was written against, so the crawl code below reads the same as Engage's.
 */
export interface CallFlowClient {
  users: {
    list(domain: string, params: { limit: number; start: number }): Promise<unknown>;
    get(domain: string, user: string): Promise<unknown>;
  };
  phoneNumbers: {
    listForDomain(domain: string, params: { limit: number; start: number }): Promise<unknown>;
  };
  autoAttendant: {
    get(domain: string, user: string, prompt: string): Promise<unknown>;
  };
  answerRules: {
    list(domain: string, user: string): Promise<unknown>;
  };
  callCenter: {
    listAgents(domain: string, queue: string): Promise<unknown>;
  };
}

// ---------------------------------------------------------------------------
// Public graph types
// ---------------------------------------------------------------------------

export type CallFlowNodeType =
  | 'ingress'
  | 'user'
  | 'auto_attendant'
  | 'call_queue'
  | 'voicemail'
  | 'offnet'
  | 'hangup'
  | 'conference'
  | 'directory'
  | 'device'
  | 'other';

export interface CallFlowNode {
  id: string;
  label: string;
  type: CallFlowNodeType;
  /** Optional background color hint (hex) — Mermaid adapter maps this to a class. */
  bg?: string;
  /** What a click opens: `user:<ext>` or `queue:<ext>` (see nodeLink). */
  link?: string;
  /** Parent node id (Cytoscape-style compound). */
  parent?: string;
  /** Free-form metadata for the side-panel drawer. */
  details?: Record<string, unknown>;
}

export interface CallFlowEdge {
  id: string;
  source: string;
  target: string;
  label?: string;
  timeframe?: string;
  priority?: number;
  /** Raw `time_range_data` for time-simulation. */
  timeRangeData?: Array<Record<string, unknown>>;
}

export interface CallFlowGraph {
  nodes: CallFlowNode[];
  edges: CallFlowEdge[];
}

// ---------------------------------------------------------------------------
// Raw NS v2 response shapes (the SDK's typings are incorrect for some of
// these — answer rules in particular — so we declare what the API actually
// returns and cast at the SDK boundary).
// ---------------------------------------------------------------------------

interface RawPhoneNumber {
  phonenumber: string;
  domain: string;
  'dial-rule-translation-destination-user'?: string;
  'dial-rule-application'?: string;
}

interface RawUser {
  user: string;
  domain: string;
  'name-first-name'?: string;
  'name-last-name'?: string;
  'email-address'?: string;
  department?: string;
  site?: string;
  'status-message'?: string;
  // Voicemail-related fields the NS user response carries directly. Used
  // by the implicit-voicemail + operator-forward edge logic. The SDK
  // doesn't include these in its User type but the API returns them on
  // the user record itself, so no extra fetch is needed.
  'voicemail-enabled'?: boolean | string; // some envs serialise as "yes"/"no"
  'voicemail-operator-forward'?: string | number;
  'voicemail-operator-forward-dial'?: string | number;
  'voicemail-operator-forward-target'?: string | number;
  'operator-forward'?: string | number;
}

interface ForwardingLogic {
  enabled: string; // "yes" | "no"
  parameters?: Array<string | number>;
}

interface RawAnswerRule {
  domain: string;
  user: string;
  'time-frame': string;
  'ordinal-priority'?: number;
  time_range_data?: Array<Record<string, unknown>>;
  'simultaneous-ring'?: ForwardingLogic;
  'forward-always'?: ForwardingLogic;
  'forward-on-busy'?: ForwardingLogic;
  'forward-no-answer'?: ForwardingLogic;
  'forward-when-unregistered'?: ForwardingLogic;
}

interface RawAaOption {
  description?: string;
  'destination-application'?: string;
  'destination-user'?: string;
  'auto-attendant'?: Record<string, unknown>; // nested AA
}

interface RawAaResponse {
  user: string;
  'starting-prompt': string;
  'attendant-name'?: string;
  'auto-attendant': Record<string, string | RawAaOption>;
  'intro-greetings'?: Array<{
    'time-frame'?: string;
    audio?: { 'ordinal-order'?: number; 'file-script-text'?: string };
  }>;
}

interface RawQueueAgent {
  'callqueue-agent-id': string;
  'callqueue-agent-dispatch-order-ordinal'?: number;
  'name-full-name'?: string;
}

// ---------------------------------------------------------------------------
// Utilities (counterparts of utils.py)
// ---------------------------------------------------------------------------

export function formatPhoneNumber(value: string): string {
  const digits = (value ?? '').replace(/\D/g, '');
  const stripped = digits.length === 11 && digits.startsWith('1') ? digits.slice(1) : digits;
  if (stripped.length === 10) {
    return `(${stripped.slice(0, 3)}) ${stripped.slice(3, 6)}-${stripped.slice(6)}`;
  }
  return value;
}

/**
 * Where a node opens when clicked. Engage linked to its own pages; here a user
 * or a queue opens in the Virtual Switchboard's side panel, so the link is a
 * `user:<ext>` / `queue:<ext>` reference the page hands to the switchboard.
 * Returns `undefined` for nodes with nothing to open.
 */
export function nodeLink(type: CallFlowNodeType, id: string): string | undefined {
  switch (type) {
    case 'user':
      return `user:${id}`;
    case 'call_queue':
      return `queue:${id}`;
    default:
      return undefined;
  }
}

// Mermaid node ids must be syntactically inert — anything other than
// [A-Za-z0-9_] gets collapsed to '_'. This also defends the SVG output
// against attacker-controlled NS field values (user names, AA prompts,
// etc.) smuggling characters that could mangle the diagram.
function safeId(value: string): string {
  return value.replace(/[^A-Za-z0-9_]/g, '_');
}

// ---------------------------------------------------------------------------
// Crawler
// ---------------------------------------------------------------------------

export interface BuildCallFlowGraphOptions {
  /** Cap on AA prompt fetches per crawl — defence against runaway recursion. */
  maxAaFetches?: number;
  /** Cap on queue agent fetches per crawl. */
  maxQueueFetches?: number;
  /** Cap on per-user detail fetches (`users.get`). Used to look up voicemail / operator-forward fields that the bulk list endpoint doesn't return. Default 200. */
  maxUserDetailFetches?: number;
  /** Hard cap on phone numbers and users fetched from NS. Defaults to 10000 (matches the Python original). */
  maxItemsPerList?: number;
  /** Hard cap on total nodes in the produced graph. Excess DIDs are skipped. Defaults to 2000. */
  maxNodes?: number;
  /** Optional progress callback (current, total) on DIDs processed. */
  onProgress?: (current: number, total: number) => void;
  /** Optional warning sink — invoked when limits trip or upstream calls fail. */
  onWarning?: (message: string) => void;
}

/**
 * Thrown when the crawl cannot read the domain at all, as opposed to reading
 * it and finding nothing.
 *
 * The two are wildly different answers and the crawler used to give the same
 * one for both: every list fetch was wrapped in a try/catch that pushed a
 * warning and returned `[]`, so a domain the caller had no permission to read
 * resolved successfully with an empty graph. The page then rendered "No call
 * flows found for this domain": a statement about the domain, and a false
 * one, with the real failure demoted to a "Partial graph" warning card
 * underneath (#4764).
 *
 * The phone-number list is the crawl's root: with no DIDs there is nothing to
 * walk, so a failure there is fatal and must reach the caller.
 */
export class CallFlowCrawlError extends Error {
  readonly domain: string;
  readonly cause?: unknown;

  constructor(domain: string, what: string, cause: unknown) {
    const detail = cause instanceof Error ? cause.message : String(cause);
    super(`Could not read ${what} for domain "${domain}": ${detail}`);
    this.name = 'CallFlowCrawlError';
    this.domain = domain;
    this.cause = cause;
  }
}

interface QueueItem {
  sourceId: string;
  targetName: string;
  targetType: CallFlowNodeType;
  edgeLabel: string;
  extra: { timeframe?: string; priority?: number; timeRangeData?: Array<Record<string, unknown>> };
  shouldExpand: boolean;
  parentHint?: string;
}

interface ExpandedChild {
  name: string;
  type: CallFlowNodeType;
  label: string;
  extra: QueueItem['extra'];
  shouldExpand: boolean;
  parentHint?: string;
}

export async function buildCallFlowGraph(
  client: CallFlowClient,
  domain: string,
  opts: BuildCallFlowGraphOptions = {},
): Promise<CallFlowGraph> {
  const maxAa = opts.maxAaFetches ?? 200;
  const maxQ = opts.maxQueueFetches ?? 200;
  const maxUserDetail = opts.maxUserDetailFetches ?? 200;
  const maxItems = opts.maxItemsPerList ?? 10_000;
  const maxNodes = opts.maxNodes ?? 2_000;
  const warn = opts.onWarning ?? (() => {});

  // Caches
  const rulesCache = new Map<string, RawAnswerRule[]>();
  const aaCache = new Map<string, RawAaResponse | null>();
  const queueCache = new Map<string, RawQueueAgent[]>();
  // Users whose answer rules sim-ring `<OwnDevices>`. Populated as a side
  // effect of `expandUser` so we can annotate the user node's label with
  // "rings all registered devices" instead of emitting a separate device
  // hop in the graph — the device hop adds no routing info (it's the
  // default behaviour for almost every extension) and creates visual
  // crossings when many extensions share the same OwnDevices node.
  const userRingsOwnDevices = new Set<string>();
  /**
   * Per-user detail cache. The bulk users.list endpoint returns a summary
   * record — `voicemail-operator-forward` and similar settings live only
   * on the per-user GET. We lazy-fetch (and cache) for the small subset
   * of users where we actually emit a voicemail edge.
   */
  const userDetailCache = new Map<string, RawUser | null>();
  let aaFetches = 0;
  let queueFetches = 0;
  let userDetailFetches = 0;
  let userDetailCapWarned = false;

  /**
   * Paginated list helper. Matches the Python original's `_get_paginated`:
   * pulls 1000 items per page until a short page is returned or the
   * `maxItems` ceiling is hit. We page via the SDK's resource methods by
   * passing `limit`/`start` params — the SDK forwards them as querystring.
   */
  const paginated = async <T>(
    fetchPage: (limit: number, start: number) => Promise<T[] | undefined>,
    label: string,
    /**
     * When set, a failure on the FIRST page throws `CallFlowCrawlError`
     * instead of warning. Used for the crawl's root list: if we never read a
     * single page there is no graph to build, and returning an empty one
     * reports "this domain has no call flows" when the truth is "we could not
     * read this domain" (#4764). A later page failing is genuinely partial:
     * we keep what we have and warn.
     */
    fatalOnFirstPage = false,
  ): Promise<T[]> => {
    const out: T[] = [];
    const pageSize = 1000;
    let start = 0;
    // Defensive iteration cap to make sure a misbehaving server can't loop forever.
    for (let i = 0; i < 100; i++) {
      let page: T[] | undefined;
      try {
        page = await fetchPage(pageSize, start);
      } catch (err) {
        if (fatalOnFirstPage && i === 0) throw new CallFlowCrawlError(domain, label, err);
        warn(`Failed to fetch ${label} (start=${start}): ${err instanceof Error ? err.message : String(err)}`);
        break;
      }
      if (!Array.isArray(page) || page.length === 0) break;
      out.push(...page);
      if (out.length >= maxItems) {
        warn(`${label} truncated at ${maxItems} items.`);
        return out.slice(0, maxItems);
      }
      if (page.length < pageSize) break;
      start += pageSize;
    }
    return out;
  };

  // Pre-fetch users for label enrichment.
  const usersMap = new Map<string, RawUser>();
  const users = await paginated<RawUser>(
    (limit, start) =>
      // The SDK's list() forwards a `params` object as querystring.
      (client.users.list(domain, { limit, start } as never) as unknown as Promise<RawUser[]>),
    'users',
  );
  for (const u of users) if (u?.user) usersMap.set(u.user, u);

  // The crawl's root. Fatal on a first-page failure: with no DIDs there is
  // nothing to walk, and an empty graph would be read as "this domain has no
  // call flows" rather than "we could not read this domain".
  const dids = await paginated<RawPhoneNumber>(
    (limit, start) =>
      (client.phoneNumbers.listForDomain(domain, { limit, start } as never) as unknown as Promise<RawPhoneNumber[]>),
    'phone numbers',
    true,
  );

  const elementsMap = new Map<string, CallFlowNode | CallFlowEdge>();
  let nodeCount = 0;
  let nodeCapHit = false;
  const upsert = (key: string, value: CallFlowNode | CallFlowEdge): boolean => {
    if (elementsMap.has(key)) return true;
    const isNode = !('source' in value);
    if (isNode) {
      if (nodeCount >= maxNodes) {
        if (!nodeCapHit) {
          nodeCapHit = true;
          warn(`Node limit reached (${maxNodes}); remaining call paths skipped.`);
        }
        return false;
      }
      nodeCount += 1;
    }
    elementsMap.set(key, value);
    return true;
  };

  const classify = (target: string | number): { type: CallFlowNodeType; name: string; parent?: string } => {
    const t = String(target ?? '');

    let m = t.match(/^\d+_callqueue_(\w+)$/);
    if (m) return { type: 'call_queue', name: m[1], parent: `user_${m[1]}` };

    m = t.match(/^\d+_attendant_(\w+)$/);
    if (m) return { type: 'user', name: m[1] };

    // NetSapiens TOD pseudo-user pattern: `<DID>_user_<extension>`. The
    // pseudo just relays to the real user, so we treat it as that user.
    // Without this rule the visualizer drew the pseudo as a generic
    // "Other:" node, which obscured the real routing.
    m = t.match(/^\d+_user_(\w+)$/);
    if (m) return { type: 'user', name: m[1] };

    m = t.match(/^\d+_pstn_(\d+)$/);
    if (m) return { type: 'offnet', name: m[1] };

    if (t.includes('Prompt') || t.includes('Announce')) return { type: 'auto_attendant', name: t };
    if (t.includes('vmail_')) return { type: 'voicemail', name: t };
    if (t.startsWith('queue_')) return { type: 'call_queue', name: t.replace('queue_', '') };
    if (t.startsWith('user_')) {
      let u = t.replace('user_', '');
      if (u.endsWith(`@${domain}`)) u = u.split('@')[0];
      return { type: 'user', name: u };
    }
    if (t.startsWith('phone_')) return { type: 'device', name: t.replace('phone_', '') };
    // NetSapiens special token meaning "ring all devices registered to this
    // user". Treat as a device node so it renders with the device style
    // instead of falling into the catch-all "Other:" bucket.
    if (t === '<OwnDevices>') return { type: 'device', name: '<OwnDevices>' };
    if (usersMap.has(t)) return { type: 'user', name: t };
    if (/^1?\d{10}$/.test(t)) return { type: 'offnet', name: t };
    if (t.toLowerCase() === 'hangup') return { type: 'hangup', name: 'Hangup' };

    return { type: 'other', name: t };
  };

  let aaCapWarned = false;
  let queueCapWarned = false;

  const getAa = async (owner: string, prompt: string): Promise<RawAaResponse | null> => {
    const key = `${owner}:${prompt}`;
    if (aaCache.has(key)) return aaCache.get(key) ?? null;
    if (aaFetches >= maxAa) {
      if (!aaCapWarned) {
        aaCapWarned = true;
        warn(`Auto-attendant fetch limit reached (${maxAa}); remaining IVR branches skipped.`);
      }
      return null;
    }
    aaFetches += 1;
    try {
      const resp = (await client.autoAttendant.get(domain, owner, prompt)) as unknown as RawAaResponse;
      aaCache.set(key, resp ?? null);
      return resp ?? null;
    } catch (err) {
      warn(`Failed to fetch auto-attendant ${owner}/${prompt}: ${err instanceof Error ? err.message : String(err)}`);
      aaCache.set(key, null);
      return null;
    }
  };

  const expandUser = async (userName: string): Promise<ExpandedChild[]> => {
    let rules = rulesCache.get(userName);
    if (!rules) {
      try {
        rules = (await client.answerRules.list(domain, userName)) as unknown as RawAnswerRule[];
      } catch (err) {
        warn(`Failed to fetch answer rules for ${userName}: ${err instanceof Error ? err.message : String(err)}`);
        rules = [];
      }
      rulesCache.set(userName, rules);
    }

    const out: ExpandedChild[] = [];
    for (const rule of rules) {
      const tfLabel = rule['time-frame'] === '*' ? 'Default' : rule['time-frame'];
      const extra = {
        timeframe: tfLabel,
        priority: rule['ordinal-priority'],
        timeRangeData: rule.time_range_data,
      };
      const fmtLabel = (action: string) => `${action} (Timeframe: ${tfLabel})`;

      // Simultaneous Ring
      const simRing = rule['simultaneous-ring'];
      const simRingTargets: Array<string | number> = [];
      if (simRing?.enabled === 'yes') {
        for (const target of simRing.parameters ?? []) {
          if (!target) continue;
          // Suppress the self-loop. NetSapiens includes the user's own
          // extension as a simul-ring parameter to mean "use the user's
          // own ring leg". When the rule also contains `<OwnDevices>`
          // (which means "ring all devices registered to this user"),
          // the bare user id is redundant and produces a self-loop edge
          // in the visualizer.
          if (String(target) === String(userName)) continue;
          // Suppress the `<OwnDevices>` device hop. It just means "ring
          // this user's registered devices" — the default behaviour for
          // almost every extension and not a separate routing hop. Track
          // it so the user node gets a "rings all registered devices"
          // label annotation, then skip emitting a child node.
          if (String(target) === '<OwnDevices>') {
            userRingsOwnDevices.add(userName);
            continue;
          }
          simRingTargets.push(target);
          const cls = classify(target);
          // AA target without owner → assume current user is the owner
          if (cls.type === 'auto_attendant' && !cls.name.includes(':')) {
            cls.name = `${userName}:${cls.name}`;
          }
          out.push({
            name: cls.name,
            type: cls.type,
            label: fmtLabel('Simultaneous Ring'),
            extra,
            shouldExpand: true,
            parentHint: cls.parent,
          });
        }
      }

      // ───────────────────────────────────────────────────────────────
      // NetSapiens TOD "User" treatment collapse.
      //
      // When a DID uses Time-of-Day routing with treatment "User", the API
      // returns an answer rule with BOTH forward-always AND forward-no-answer
      // enabled:
      //   forward-always:    ["<DID>_user_<X>"]   (a pseudo that rings X's devices)
      //   forward-no-answer: [X, "(First", "Last)"]
      // The NetSapiens portal shows this as a single "User → X" treatment.
      // To match that view, when we detect the pattern (forward-always
      // points to `<digits>_user_<X>` AND forward-no-answer points to the
      // same user X) we emit ONE edge labeled with just the timeframe
      // instead of two technically-redundant edges.
      const fa = rule['forward-always'];
      const fna = rule['forward-no-answer'];
      let collapsed = false;
      if (
        fa?.enabled === 'yes' &&
        fna?.enabled === 'yes' &&
        fa.parameters?.length &&
        fna.parameters?.length
      ) {
        const faTarget = String(fa.parameters[0]);
        const fnaTarget = String(fna.parameters[0]);
        const m = faTarget.match(/^\d+_user_(\w+)$/);
        if (m && m[1] === fnaTarget) {
          const cls = classify(fnaTarget);
          out.push({
            name: cls.name,
            type: cls.type,
            label: `User (Timeframe: ${tfLabel})`,
            extra,
            shouldExpand: true,
            parentHint: cls.parent,
          });
          collapsed = true;
        }
      }

      const forwards: Array<[string, ForwardingLogic | undefined]> = collapsed
        ? [
            // Both fields consumed by the collapse above; only emit
            // busy / unregistered if separately enabled.
            ['Forward Busy', rule['forward-on-busy']],
            ['Forward Offline', rule['forward-when-unregistered']],
          ]
        : [
            ['Forward Always', rule['forward-always']],
            ['Forward Busy', rule['forward-on-busy']],
            ['Forward No Answer', rule['forward-no-answer']],
            ['Forward Offline', rule['forward-when-unregistered']],
          ];
      let emittedAnyForward = false;
      for (const [name, fwd] of forwards) {
        if (fwd?.enabled !== 'yes' || !fwd.parameters?.length) continue;
        const target = fwd.parameters[0];
        if (!target) continue;
        const cls = classify(target);
        if (cls.type === 'auto_attendant' && !cls.name.includes(':')) {
          cls.name = `${userName}:${cls.name}`;
        }
        out.push({
          name: cls.name,
          type: cls.type,
          label: fmtLabel(name),
          extra,
          shouldExpand: true,
          parentHint: cls.parent,
        });
        emittedAnyForward = true;
      }

      // Implicit voicemail fallback.
      // NetSapiens default behaviour: when a rule rings the user's devices
      // (simul-ring or `<OwnDevices>`) but has NO explicit forward-no-answer
      // and no forward-on-active/busy/unregistered, the call falls through
      // to the user's voicemail after the ring timeout. The rule fields
      // don't encode this — it's implicit. We add an edge to make the
      // behaviour visible.
      //
      // We skip TOD pseudo-users (e.g. `19043891130` — all-digits, ≥10
      // chars) because their "no answer" path is the actual user, not
      // voicemail. The TOD User-treatment collapse above already handles
      // their fallthrough explicitly.
      const isTodPseudo = /^\d{10,11}$/.test(userName);
      const ringsDevices =
        simRing?.enabled === 'yes' &&
        (simRingTargets.length > 0 ||
          (simRing.parameters ?? []).some((p) => String(p) === '<OwnDevices>'));

      // Voicemail-enabled gate. The summary record from users.list often
      // omits `voicemail-enabled`, so when the summary doesn't say either
      // way we fall through to a per-user detail fetch (cached + capped).
      // This is also the fetch expandVoicemail will reuse to find the
      // operator-forward target, so it's not duplicated work.
      const summary = usersMap.get(userName);
      const summaryHasFlag =
        summary &&
        (summary['voicemail-enabled'] === true ||
          summary['voicemail-enabled'] === false ||
          summary['voicemail-enabled'] === 'yes' ||
          summary['voicemail-enabled'] === 'no');
      let vmExplicitlyDisabled =
        summaryHasFlag &&
        (summary!['voicemail-enabled'] === false ||
          summary!['voicemail-enabled'] === 'no');

      const willConsiderImplicitVm =
        ringsDevices &&
        !emittedAnyForward &&
        !collapsed &&
        !isTodPseudo &&
        rule['forward-no-answer']?.enabled !== 'yes' &&
        rule['forward-on-busy']?.enabled !== 'yes' &&
        rule['forward-when-unregistered']?.enabled !== 'yes';

      if (willConsiderImplicitVm && !summaryHasFlag) {
        const detail = await fetchUserDetails(userName);
        if (
          detail &&
          (detail['voicemail-enabled'] === false ||
            detail['voicemail-enabled'] === 'no')
        ) {
          vmExplicitlyDisabled = true;
        }
      }

      if (willConsiderImplicitVm && !vmExplicitlyDisabled) {
        out.push({
          name: `vmail_${userName}`,
          type: 'voicemail',
          label: `Voicemail (implicit, no answer)`,
          extra,
          // Expand the voicemail node so the operator-forward edge (press 0
          // from the mailbox) gets rendered as well.
          shouldExpand: true,
        });
      }
    }
    return out;
  };

  const expandAa = async (nodeName: string): Promise<ExpandedChild[]> => {
    const [owner, prompt] = nodeName.includes(':') ? nodeName.split(':') : [nodeName, nodeName];
    const aa = await getAa(owner, prompt);
    if (!aa) return [];

    // Intro-greeting detection: if this prompt is "Announce-N" for an
    // existing intro, the only outgoing edge is to the main AA.
    if (prompt.includes('Announce') && aa['intro-greetings']) {
      const digits = prompt.match(/\d+/g);
      if (digits?.length) {
        const targetId = parseInt(digits[digits.length - 1], 10);
        const isIntro = aa['intro-greetings'].some(
          (g) => g?.audio?.['ordinal-order'] === targetId,
        );
        if (isIntro && aa['starting-prompt']) {
          return [
            {
              name: `${owner}:${aa['starting-prompt']}`,
              type: 'auto_attendant',
              label: 'Next',
              extra: {},
              shouldExpand: true,
            },
          ];
        }
      }
    }

    const out: ExpandedChild[] = [];
    for (const [key, option] of Object.entries(aa['auto-attendant'] ?? {})) {
      let label = key;
      if (key === 'no-key-press') label = 'No Input';
      else if (key === 'unassigned-key-press') label = 'Invalid Input';
      else if (key.startsWith('option-')) label = `Press ${key.replace('option-', '')}`;
      else continue;

      // "repeat" string value → loop back to self
      if (typeof option === 'string') {
        if (option === 'repeat') {
          out.push({ name: nodeName, type: 'auto_attendant', label, extra: {}, shouldExpand: false });
        }
        continue;
      }

      const opt = option;

      // Nested AA
      if (opt['auto-attendant']) {
        const syntheticPrompt = `${prompt}:nested_${key}`;
        const syntheticId = `${owner}:${syntheticPrompt}`;
        aaCache.set(syntheticId, {
          user: owner,
          'starting-prompt': syntheticPrompt,
          'attendant-name': `Nested ${label}`,
          'auto-attendant': opt['auto-attendant'] as Record<string, string | RawAaOption>,
        });
        out.push({ name: syntheticId, type: 'auto_attendant', label, extra: {}, shouldExpand: true });
        continue;
      }

      // Company directory
      const app = opt['destination-application'];
      if (app && app.includes('sip:start') && app.includes('directory')) {
        out.push({ name: 'Directory', type: 'directory', label, extra: {}, shouldExpand: false });
        continue;
      }

      const dest = opt['destination-user'] ?? '';
      let cls = classify(dest);

      if (app === 'hangup') cls = { type: 'hangup', name: 'Hangup' };
      else if (app === 'voicemail') cls.type = 'voicemail';
      else if (app === 'repeat-tier') {
        cls.type = 'auto_attendant';
        cls.name = nodeName;
      } else if (app === 'callcenter') cls.type = 'call_queue';
      else if (app === 'to-single-device' && dest.includes('.')) {
        cls = { type: 'conference', name: dest.split('.')[0] };
      }

      if (cls.name) {
        out.push({
          name: cls.name,
          type: cls.type,
          label,
          extra: {},
          shouldExpand: true,
          parentHint: cls.parent,
        });
      }
    }
    return out;
  };

  const expandQueue = async (queueName: string): Promise<ExpandedChild[]> => {
    let agents = queueCache.get(queueName);
    if (!agents) {
      if (queueFetches >= maxQ) {
        if (!queueCapWarned) {
          queueCapWarned = true;
          warn(`Queue agent fetch limit reached (${maxQ}); remaining queue rosters skipped.`);
        }
        return [];
      }
      queueFetches += 1;
      try {
        agents = (await client.callCenter.listAgents(domain, queueName)) as unknown as RawQueueAgent[];
      } catch (err) {
        warn(`Failed to fetch agents for queue ${queueName}: ${err instanceof Error ? err.message : String(err)}`);
        agents = [];
      }
      queueCache.set(queueName, agents);
    }
    return agents
      .filter((a) => a['callqueue-agent-id'])
      .map((a) => {
        // NetSapiens returns agent ids in a few shapes:
        //   "2280@TeleVoIPs-Internal"
        //   "sip:2203@TeleVoIPs-Internal"
        //   "agent1"        (test/fixture style — no scheme, no domain)
        // Normalise to the bare extension so the rendering loop can look
        // the user up in `usersMap` and substitute the friendly name.
        let agentId = String(a['callqueue-agent-id']);
        agentId = agentId.replace(/^sip:/i, '');
        if (agentId.endsWith(`@${domain}`)) {
          agentId = agentId.split('@')[0];
        }
        return {
          name: agentId,
          type: 'user' as CallFlowNodeType,
          label: 'Agent',
          extra: {},
          shouldExpand: false,
        };
      });
  };

  /**
   * Look up a user's full detail record. The bulk `users.list` endpoint
   * returns a summary that omits voicemail-* settings, so for users where
   * we need to know the voicemail-enabled flag or operator-forward target
   * we issue an opportunistic per-user GET. Cached so repeat lookups
   * (multiple rules referencing the same user) only hit the API once.
   */
  const fetchUserDetails = async (userKey: string): Promise<RawUser | null> => {
    if (userDetailCache.has(userKey)) return userDetailCache.get(userKey) ?? null;
    if (userDetailFetches >= maxUserDetail) {
      if (!userDetailCapWarned) {
        userDetailCapWarned = true;
        warn(`User-detail fetch limit reached (${maxUserDetail}); remaining voicemail settings will use cached summary data only.`);
      }
      userDetailCache.set(userKey, null);
      return null;
    }
    userDetailFetches += 1;
    try {
      const detail = (await client.users.get(domain, userKey)) as unknown as RawUser;
      userDetailCache.set(userKey, detail ?? null);
      return detail ?? null;
    } catch (err) {
      warn(`Failed to fetch user details for ${userKey}: ${err instanceof Error ? err.message : String(err)}`);
      userDetailCache.set(userKey, null);
      return null;
    }
  };

  const readOperatorForward = (record: RawUser | null | undefined): string | number | undefined => {
    if (!record) return undefined;
    return (
      record['voicemail-operator-forward-target'] ??
      record['voicemail-operator-forward-dial'] ??
      record['voicemail-operator-forward'] ??
      record['operator-forward']
    );
  };

  /**
   * Expand a voicemail node (`vmail_<user>`) into its operator-forward
   * destination. NetSapiens lets the mailbox owner configure an
   * "Operator Forward" target — pressing 0 from inside the mailbox routes
   * the caller to that extension. The bulk users.list record doesn't
   * include this field, so we issue a per-user GET (cached + capped).
   */
  const expandVoicemail = async (nodeName: string): Promise<ExpandedChild[]> => {
    const userKey = nodeName.replace(/^vmail_/, '');
    // Try the summary first — if the field happens to be there, skip the
    // detail call. Otherwise fetch the full record.
    let target = readOperatorForward(usersMap.get(userKey));
    if (target === undefined) {
      const detail = await fetchUserDetails(userKey);
      target = readOperatorForward(detail);
    }
    if (target === undefined || target === null || target === '') return [];
    const cls = classify(String(target));
    if (!cls.name) return [];
    return [
      {
        name: cls.name,
        type: cls.type,
        label: 'Operator Forward (press 0)',
        extra: {},
        shouldExpand: true,
        parentHint: cls.parent,
      },
    ];
  };

  // Process each DID sequentially. Could be parallel, but per-DID work is
  // already async-heavy and we want predictable load on the NS API.
  let didIdx = 0;
  for (const didObj of dids) {
    didIdx += 1;
    opts.onProgress?.(didIdx, dids.length);
    if (!didObj?.['dial-rule-translation-destination-user']) continue;

    const did = didObj.phonenumber;
    const dest = didObj['dial-rule-translation-destination-user'];
    const rootId = safeId(`did_${did}`);

    const ingressAdded = upsert(rootId, {
      id: rootId,
      label: `Phone Number: ${formatPhoneNumber(did)}`,
      type: 'ingress',
      bg: '#E0E0E0',
      link: nodeLink('ingress', did),
      details: {
        Destination: dest,
        Application: didObj['dial-rule-application'],
      },
    });
    if (!ingressAdded) break; // node cap reached — stop the whole crawl

    const visited = new Set<string>([rootId]);
    const initial = classify(dest);
    const queue: QueueItem[] = [
      {
        sourceId: rootId,
        targetName: initial.name,
        targetType: initial.type,
        edgeLabel: 'Destination',
        extra: {},
        shouldExpand: true,
        parentHint: initial.parent,
      },
    ];

    while (queue.length) {
      const item = queue.shift()!;
      const rawNodeId = `${item.targetType}_${item.targetName}`;
      const nodeId = safeId(rawNodeId);
      // Edge id must include the label + priority + timeframe so two rules
      // that target the same node (e.g. Tech DayNight → 2201 and Default →
      // 2201 in a TOD setup) don't collapse to the same id and lose one of
      // the rules. Previously this was `edge_<src>_<tgt>`, which silently
      // dropped the second rule via dedup.
      const edgeId = safeId(
        `edge_${item.sourceId}_${nodeId}_${item.edgeLabel}_p${item.extra.priority ?? ''}_t${item.extra.timeframe ?? ''}`,
      );

      upsert(edgeId, {
        id: edgeId,
        source: safeId(item.sourceId),
        target: nodeId,
        label: item.edgeLabel,
        timeframe: item.extra.timeframe,
        priority: item.extra.priority,
        timeRangeData: item.extra.timeRangeData,
      });

      if (visited.has(nodeId)) continue;
      visited.add(nodeId);

      let label = item.targetName;
      let bg = '#ADD8E6';
      let link = nodeLink(item.targetType, item.targetName);
      let parent = item.parentHint ? safeId(item.parentHint) : undefined;
      let details: Record<string, unknown> = {};

      if (item.targetType === 'user') {
        const u = usersMap.get(item.targetName);
        if (u) {
          const full = `${u['name-first-name'] ?? ''} ${u['name-last-name'] ?? ''}`.trim();
          if (full) label = `${full} (${item.targetName})`;
          const d: Record<string, unknown> = {
            Email: u['email-address'],
            Department: u.department,
            Site: u.site,
            Status: u['status-message'],
          };
          for (const k of Object.keys(d)) if (!d[k]) delete d[k];
          details = d;
        }
      } else if (item.targetType === 'auto_attendant') {
        bg = '#FFD700';
        if (item.targetName.includes(':')) {
          const [owner, prompt] = item.targetName.split(':');
          const aa = await getAa(owner, prompt);
          if (aa) {
            const aaName = aa['attendant-name'] || 'Auto Attendant';
            const start = aa['starting-prompt'] || prompt;
            details = { 'Attendant Name': aaName, 'Starting Prompt': start, Owner: owner };

            let isIntro = false;
            if (prompt.includes('Announce') && aa['intro-greetings']) {
              const digits = prompt.match(/\d+/g);
              if (digits?.length) {
                const targetId = parseInt(digits[digits.length - 1], 10);
                for (const g of aa['intro-greetings']) {
                  if (g?.audio?.['ordinal-order'] === targetId) {
                    if (g.audio['file-script-text']) {
                      details['Intro Script'] = g.audio['file-script-text'];
                    }
                    if (g['time-frame']) {
                      label = `Intro Greeting: ${g['time-frame']} (${targetId})`;
                      // Re-parent to the main AA
                      parent = safeId(`auto_attendant_${owner}:${start}`);
                      isIntro = true;
                    }
                    break;
                  }
                }
              }
            }
            if (!isIntro) label = `${aaName} (${start})`;
          } else {
            label = `Auto Attendant: ${prompt}`;
          }
        } else {
          label = `Auto Attendant: ${item.targetName}`;
        }
        // Group nested AAs under the parent AA node
        if (!parent && item.sourceId.startsWith('auto_attendant_') && item.targetName.includes('nested_')) {
          parent = safeId(item.sourceId);
        }
      } else if (item.targetType === 'call_queue') {
        bg = '#FFA500';
        label = `Queue: ${item.targetName}`;
        const potentialParent = safeId(`user_${item.targetName}`);
        if (item.sourceId === potentialParent) parent = potentialParent;
      } else if (item.targetType === 'voicemail') {
        bg = '#A9A9A9';
        if (item.targetName.includes('vmail_')) {
          label = `Voicemail (${item.targetName.replace('vmail_', '')})`;
        }
      } else if (item.targetType === 'offnet') {
        bg = '#90EE90';
        label = `External: ${formatPhoneNumber(item.targetName)}`;
        link = undefined;
      } else if (item.targetType === 'hangup') {
        bg = '#FF6347';
        label = 'Hangup';
        link = undefined;
      } else if (item.targetType === 'directory') {
        bg = '#DA70D6';
        label = 'Directory';
        link = undefined;
      } else if (item.targetType === 'conference') {
        bg = '#EE82EE';
        label = `Conference Bridge: ${item.targetName}`;
      } else if (item.targetType === 'device') {
        bg = '#D8BFD8';
        label =
          item.targetName === '<OwnDevices>'
            ? 'Own Devices (all registered)'
            : `Device: ${item.targetName}`;
        link = undefined;
      } else if (item.targetType === 'other') {
        bg = '#D3D3D3';
        label = `Other: ${item.targetName}`;
        link = undefined;
      }

      const nodeAdded = upsert(nodeId, {
        id: nodeId,
        label,
        type: item.targetType,
        bg,
        link,
        parent,
        details: Object.keys(details).length ? details : undefined,
      });
      // If we hit the cap, don't expand this node's children — the warning
      // has already been emitted by upsert(). Continue the loop so the
      // remaining DIDs still get their edges drawn back to existing nodes.
      if (!nodeAdded || !item.shouldExpand) continue;

      let children: ExpandedChild[] = [];
      if (item.targetType === 'user') {
        children = await expandUser(item.targetName);
        // expandUser populates `userRingsOwnDevices` as a side effect.
        // Append a "rings all registered devices" sub-line to the user
        // node label so the implicit device behaviour is visible without
        // adding a separate device node to the graph. Skip TOD pseudo
        // users (10-11 digit ids) — they're routing constructs, not
        // real users with devices, so the annotation would mislead.
        const isTodPseudo = /^\d{10,11}$/.test(item.targetName);
        if (userRingsOwnDevices.has(item.targetName) && !isTodPseudo) {
          const userNode = elementsMap.get(nodeId);
          // The map stores both nodes and edges; narrow to node via the
          // absence of `source` (edges always carry one).
          if (
            userNode &&
            !('source' in userNode) &&
            !userNode.label.includes('rings all registered devices')
          ) {
            userNode.label = `${userNode.label}\nrings all registered devices`;
          }
        }
      } else if (item.targetType === 'auto_attendant') children = await expandAa(item.targetName);
      else if (item.targetType === 'call_queue') children = await expandQueue(item.targetName);
      else if (item.targetType === 'voicemail') children = await expandVoicemail(item.targetName);

      for (const child of children) {
        queue.push({
          sourceId: nodeId,
          targetName: child.name,
          targetType: child.type,
          edgeLabel: child.label,
          extra: child.extra,
          shouldExpand: child.shouldExpand,
          parentHint: child.parentHint,
        });
      }
    }
  }

  const nodes: CallFlowNode[] = [];
  const edges: CallFlowEdge[] = [];
  for (const el of elementsMap.values()) {
    if ('source' in el) edges.push(el);
    else nodes.push(el);
  }
  return { nodes, edges };
}

// ---------------------------------------------------------------------------
// Filtering helpers
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Time simulation
// ---------------------------------------------------------------------------

interface TimeRange {
  'start-date'?: string; // "YYYY-MM-DD" or "now" / "never"
  'end-date'?: string;
  // Sunday arrives as either 0 or 7 depending on the switch; Mon-Sat are 1-6
  // under both conventions. See `matchesDayOfWeek`.
  'day-of-week-number'?: string | number; // 1=Mon..6=Sat, Sunday 0 or 7, or "*"
  'start-time'?: string; // "HH:MM"
  'end-time'?: string;
}

/**
 * Does a NetSapiens `day-of-week-number` name the simulated day?
 *
 * The switch is not consistent about Sunday. ISO numbers it 7 (1=Mon..7=Sun),
 * which is what `computeSimulation` produces, but real responses also carry a
 * 0 for it (see the captured payload in the "collapses TOD User-treatment
 * rules" case of `callflow-graph.test.ts`), the C/JS convention where
 * 0=Sun..6=Sat. Monday through Saturday are 1-6 under both, so Sunday is the
 * only day the two disagree on, and it was the only day that could never
 * match: a rule scoped to Sunday was silently inactive at every moment.
 *
 * Accepting both spellings is safe in either direction, because neither
 * convention uses 0 and 7 for different days.
 */
function matchesDayOfWeek(rDay: string | number, simNsDay: number): boolean {
  const raw = String(rDay).trim();
  if (raw === String(simNsDay)) return true;
  // Sunday is 7 in `sim`, so also honour a 0 from a switch using 0=Sun.
  return simNsDay === 7 && raw === '0';
}

/**
 * Decide whether a single NS time-range entry covers the simulated moment.
 * Matches the logic in the original Python tool's
 * `route_graph_inventory_tab.js::isRangeMatch`.
 */
function rangeMatchesAt(range: TimeRange, sim: { date: string; time: string; nsDay: number }): boolean {
  const rStart = range['start-date'];
  const rEnd = range['end-date'];
  const isSpecific = !!(rStart && rStart !== 'now' && rStart !== 'never');

  if (isSpecific) {
    // Holiday / one-off window — must fall inside the date span
    if (sim.date < (rStart as string) || sim.date > (rEnd as string)) return false;
  } else {
    // Recurring rule — must match day of week (or be "any")
    const rDay = range['day-of-week-number'];
    if (rDay !== undefined && rDay !== null && rDay !== '*' && !matchesDayOfWeek(rDay, sim.nsDay)) {
      return false;
    }
  }

  const startT = range['start-time'];
  const endT = range['end-time'];
  if (startT && endT) {
    if (startT <= endT) {
      // Same-day window
      return sim.time >= startT && sim.time <= endT;
    }
    // Cross-midnight window (e.g. 22:00–06:00) — the range wraps, so a
    // match means EITHER side of midnight contains sim.time.
    return sim.time >= startT || sim.time <= endT;
  }
  return true;
}

export interface SimulationResult {
  /** Edge ids the simulator considers inactive at the simulated time. */
  inactiveEdgeIds: Set<string>;
  /** Distinct timeframe names that "won" at the simulated time. */
  activeTimeframes: string[];
  /**
   * Source-node ids where the simulator had to fall through to the lowest-
   * precedence group because no group's time ranges matched. Surfaced so the
   * UI can hint that the "Default" rule is acting as the catch-all.
   */
  fallthroughSourceIds: string[];
}

/**
 * Given a graph and a simulated date/time, decide which outgoing edges are
 * *inactive* (i.e. wouldn't be followed at that moment because a
 * higher-precedence answer rule wins) and report which timeframes carried
 * the call.
 *
 * Algorithm (per source node):
 *   1. Group outgoing edges by priority (undefined → 9999).
 *   2. Walk priorities ascending. For each group, peek at the first edge's
 *      `time_range_data`: if it has no ranges OR at least one range matches
 *      the simulated moment, this group "wins".
 *   3. If nothing wins via explicit time matching, the lowest-precedence
 *      group (highest priority number, conventionally "Default") wins by
 *      fall-through — that matches NetSapiens' real behaviour where the
 *      catch-all rule sits at the bottom of the priority stack.
 *   4. Every non-winning group's edges with `time_range_data` go in the
 *      inactive set. Unconditional edges (AA menu presses, queue agents)
 *      are never dimmed because they don't depend on a timeframe.
 */
export function computeSimulation(graph: CallFlowGraph, simDate: Date): SimulationResult {
  const inactive = new Set<string>();
  const activeTimeframes = new Set<string>();
  const fallthroughSourceIds: string[] = [];
  if (!graph.edges.length) {
    return { inactiveEdgeIds: inactive, activeTimeframes: [], fallthroughSourceIds: [] };
  }

  // Pre-compute simulation context
  const jsDay = simDate.getDay(); // 0=Sun..6=Sat
  const nsDay = jsDay === 0 ? 7 : jsDay; // ISO: 1=Mon..7=Sun
  const time = `${String(simDate.getHours()).padStart(2, '0')}:${String(simDate.getMinutes()).padStart(2, '0')}`;
  const date = `${simDate.getFullYear()}-${String(simDate.getMonth() + 1).padStart(2, '0')}-${String(simDate.getDate()).padStart(2, '0')}`;
  const sim = { date, time, nsDay };

  // Group edges by source
  const bySource = new Map<string, CallFlowEdge[]>();
  for (const e of graph.edges) {
    if (!bySource.has(e.source)) bySource.set(e.source, []);
    bySource.get(e.source)!.push(e);
  }

  for (const [sourceId, edges] of bySource.entries()) {
    // Skip sources that have no timeframe-bound edges at all — they're
    // unconditional links (e.g. AA option presses).
    const hasAnyTimeframe = edges.some((e) => e.timeRangeData && e.timeRangeData.length > 0);
    if (!hasAnyTimeframe) continue;

    // Bucket by priority
    const groups = new Map<number, CallFlowEdge[]>();
    for (const e of edges) {
      const p = e.priority ?? 9999;
      if (!groups.has(p)) groups.set(p, []);
      groups.get(p)!.push(e);
    }

    const priorities = Array.from(groups.keys()).sort((a, b) => a - b);
    let winner: CallFlowEdge[] | null = null;
    let fellThrough = false;

    for (const p of priorities) {
      const group = groups.get(p)!;
      const ranges = (group[0]?.timeRangeData as TimeRange[] | undefined) ?? undefined;
      const matches = !ranges || ranges.length === 0 || ranges.some((r) => rangeMatchesAt(r, sim));
      if (matches) {
        winner = group;
        break;
      }
    }

    // Fall-through: if no group matched via time ranges, the
    // lowest-precedence group (last after ascending sort, conventionally
    // "Default") becomes the de-facto winner. Real NetSapiens behaviour
    // is "the Default rule fires when no other timeframe applies".
    if (!winner && priorities.length > 0) {
      winner = groups.get(priorities[priorities.length - 1]) ?? null;
      fellThrough = true;
      fallthroughSourceIds.push(sourceId);
    }

    if (winner) {
      for (const e of winner) {
        if (e.timeframe) activeTimeframes.add(e.timeframe);
      }
    }
    void fellThrough;

    for (const e of edges) {
      if (winner && winner.includes(e)) continue;
      // Dim every answer-rule edge that lost the contest. The discriminator
      // is `timeframe`, NOT `timeRangeData`: NetSapiens emits no
      // `time_range_data` for a wildcard ("*") rule, so keying on the ranges
      // left the Default branch drawn as live even when it had lost. In the
      // common setup (an explicit "After Hours" rule plus a wildcard Default
      // carrying the daytime path) that meant simulating an evening dimmed
      // nothing at all and the diagram was byte-identical to the unsimulated
      // one. The tool looked broken in exactly one direction (#4763).
      //
      // Unconditional links carry neither and stay solid: only `expandUser`
      // attaches the rule's `extra` (timeframe / priority / ranges) to its
      // children, while AA menu presses, queue agents and directory hops are
      // all built with `extra: {}`. The source-level `hasAnyTimeframe` gate
      // above has already skipped any node where no timeframe contest took
      // place.
      //
      // The ranges are kept in the test as well as the timeframe so this
      // stays a strict widening of the old rule: nothing that dimmed before
      // stops dimming now.
      if (e.timeframe || (e.timeRangeData && e.timeRangeData.length > 0)) {
        inactive.add(e.id);
      }
    }
  }

  return {
    inactiveEdgeIds: inactive,
    activeTimeframes: Array.from(activeTimeframes).sort(),
    fallthroughSourceIds,
  };
}

/**
 * Back-compat shim. Returns only the inactive edge ids (the most common
 * use). New code should call `computeSimulation` to also get the active
 * timeframes and fall-through hints.
 */
export function computeInactiveEdges(graph: CallFlowGraph, simDate: Date): Set<string> {
  return computeSimulation(graph, simDate).inactiveEdgeIds;
}

/**
 * Restrict a graph to the set of nodes reachable from any of `rootIds`.
 * Useful for the "Phone Number Filter" feature — pass the ingress node ids
 * you want to keep and discard everything else.
 */
export function filterGraphToRoots(graph: CallFlowGraph, rootIds: string[]): CallFlowGraph {
  if (!rootIds.length) return { nodes: [], edges: [] };
  const adjacency = new Map<string, string[]>();
  for (const e of graph.edges) {
    if (!adjacency.has(e.source)) adjacency.set(e.source, []);
    adjacency.get(e.source)!.push(e.target);
  }
  const reachable = new Set<string>();
  const stack = [...rootIds];
  while (stack.length) {
    const id = stack.pop()!;
    if (reachable.has(id)) continue;
    reachable.add(id);
    for (const next of adjacency.get(id) ?? []) stack.push(next);
  }
  return {
    nodes: graph.nodes.filter((n) => reachable.has(n.id)),
    edges: graph.edges.filter((e) => reachable.has(e.source) && reachable.has(e.target)),
  };
}
