/**
 * The call-flow diagram: laid out by callflow/layout.ts (dagre) and drawn here
 * as plain SVG, with pan, zoom, fit, full screen, PNG / SVG download and
 * clickable nodes. The controls follow the Engage viewer
 * (client/src/pages/numbers/CallFlowViewer.tsx); the drawing replaces Mermaid,
 * which is too large for a Horizon app (see layout.ts). Differences from
 * Engage:
 *
 *   - The wheel listener is native and non-passive. React attaches wheel
 *     handlers as passive, so Engage's preventDefault() was ignored and the
 *     page scrolled while the diagram zoomed.
 *   - Nodes that open something are real keyboard buttons (Tab, Enter or
 *     Space), named by their label; a press that moved (a pan) is not a click.
 *   - Labels are SVG text, so the PNG download works in Chrome (Mermaid's HTML
 *     labels taint the canvas there) and the SVG opens in drawing tools.
 *   - Layout runs after the "Drawing the diagram" message has painted, so a
 *     large domain does not look frozen.
 *
 * The stage is always light: the node colours are a fixed light palette with
 * black text, which would be an unreadable island on a dark canvas (the same
 * choice Engage made).
 */
import type * as React from 'react';
import { memo, useCallback, useEffect, useRef, useState } from 'react';

import { useKit } from '../ui/kit';
import { ActionIcon, SmallButton } from '../ui/bits';
import type { CallFlowGraph } from './graph';
import {
  EDGE_LINE,
  FONT_FAMILY,
  GROUP_FONT,
  GROUP_PAD,
  HEX_INSET,
  NODE_LINE,
  basisPath,
  layoutGraph,
  type LaidOutEdge,
  type LaidOutGroup,
  type LaidOutNode,
  type Layout,
} from './layout';

const MIN_SCALE = 0.05;
const MAX_SCALE = 5;
const ZOOM_STEP = 1.2;
/** Pointer travel (px) that turns a press into a pan rather than a click. */
const DRAG_SLOP = 4;
/** Space kept around the diagram when fitting it to the stage. */
const FIT_PADDING = 32;
/** The largest PNG we try to make (canvas memory), in pixels. */
const MAX_PNG_PIXELS = 40_000_000;

const STROKE = '#333333';
const DIM = '#b4b8c0';
const SELECTED = '#1d4ed8';

let measureCtx: CanvasRenderingContext2D | null | undefined;
const measureCache = new Map<string, number>();

/** Text width in px, from the same font the SVG draws with. */
function measureText(text: string, font: string): number {
  const key = `${font}|${text}`;
  const hit = measureCache.get(key);
  if (hit !== undefined) return hit;
  if (measureCtx === undefined) {
    try {
      measureCtx = document.createElement('canvas').getContext('2d');
    } catch {
      measureCtx = null;
    }
  }
  let width: number;
  if (measureCtx) {
    measureCtx.font = font;
    width = measureCtx.measureText(text).width;
  } else {
    const px = Number(/(\d+(?:\.\d+)?)px/.exec(font)?.[1] ?? 14);
    width = text.length * px * 0.56;
  }
  if (measureCache.size > 5000) measureCache.clear();
  measureCache.set(key, width);
  return width;
}

let viewerSeq = 0;

interface View {
  s: number;
  x: number;
  y: number;
}

const clampScale = (s: number) => Math.max(MIN_SCALE, Math.min(MAX_SCALE, s));

export interface ViewerProps {
  graph: CallFlowGraph;
  /** Edge ids drawn greyed out and dashed (the time simulator's losing routes). */
  inactiveEdgeIds?: ReadonlySet<string>;
  /** Node ids that open something when selected; others are not focusable. */
  selectable?: ReadonlySet<string>;
  /** Plain-text label per node id, for the accessible name. */
  labels?: ReadonlyMap<string, string>;
  selectedId?: string | null;
  onSelect?: (id: string | null) => void;
  /** Rendered over the stage's top-right corner (the node details card). */
  overlay?: React.ReactNode;
  /** Download file names, without extension. */
  fileName?: string;
}

export function CallFlowViewer({ graph, inactiveEdgeIds, selectable, labels, selectedId, onSelect, overlay, fileName = 'call-flow' }: ViewerProps) {
  const { Box, Typography, Alert } = useKit();
  const wrapperRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const svgRef = useRef<SVGSVGElement>(null);
  const [uid] = useState(() => `cf${++viewerSeq}`);
  const [layout, setLayout] = useState<Layout | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [fullscreen, setFullscreen] = useState(false);
  const [view, setView] = useState<View>({ s: 1, x: 0, y: 0 });
  const [panning, setPanning] = useState(false);
  const viewRef = useRef(view);
  viewRef.current = view;
  const layoutRef = useRef(layout);
  layoutRef.current = layout;
  const pan = useRef<{ startX: number; startY: number; baseX: number; baseY: number; moved: boolean } | null>(null);
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;

  // Lay out a new graph. The timeout lets "Drawing the diagram" paint first;
  // dagre is synchronous and a large domain takes a moment.
  useEffect(() => {
    let cancelled = false;
    setLayout(null);
    setError(null);
    const t = setTimeout(() => {
      try {
        const next = layoutGraph(graph, { measure: measureText });
        if (!cancelled) setLayout(next);
      } catch (err) {
        console.error('[switchboard] call flow layout failed:', err);
        if (!cancelled) setError('The diagram could not be drawn.');
      }
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, [graph]);

  const fitToView = useCallback(() => {
    const stage = stageRef.current;
    const l = layoutRef.current;
    if (!stage || !l || !l.width || !l.height) return;
    const rect = stage.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const s = clampScale(Math.min((rect.width - FIT_PADDING * 2) / l.width, (rect.height - FIT_PADDING * 2) / l.height, 1));
    setView({ s, x: (rect.width - l.width * s) / 2, y: Math.max(FIT_PADDING / 2, (rect.height - l.height * s) / 2) });
  }, []);

  // Fit each new layout once (a new domain, or a different set of numbers),
  // not when the time simulator only greys routes out.
  useEffect(() => {
    if (layout) fitToView();
  }, [layout, fitToView]);

  // Native, non-passive wheel zoom (React's wheel listener is passive).
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return;
    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      const rect = stage.getBoundingClientRect();
      zoomAt(e.deltaY < 0 ? ZOOM_STEP : 1 / ZOOM_STEP, e.clientX - rect.left, e.clientY - rect.top);
    };
    stage.addEventListener('wheel', onWheel, { passive: false });
    return () => stage.removeEventListener('wheel', onWheel);
  }, []);

  useEffect(() => {
    const onChange = () => {
      setFullscreen(document.fullscreenElement === wrapperRef.current);
      requestAnimationFrame(() => fitToView());
    };
    document.addEventListener('fullscreenchange', onChange);
    return () => document.removeEventListener('fullscreenchange', onChange);
  }, [fitToView]);

  function zoomAt(factor: number, cx: number, cy: number) {
    setView((v) => {
      const s = clampScale(v.s * factor);
      if (s === v.s) return v;
      const r = s / v.s;
      return { s, x: cx - (cx - v.x) * r, y: cy - (cy - v.y) * r };
    });
  }
  const zoomCentre = (factor: number) => {
    const rect = stageRef.current?.getBoundingClientRect();
    if (rect) zoomAt(factor, rect.width / 2, rect.height / 2);
  };

  const nodeIdAt = (target: EventTarget | null): string | null =>
    (target as Element | null)?.closest?.('[data-node-id]')?.getAttribute('data-node-id') ?? null;

  const onPointerDown = (e: React.PointerEvent) => {
    if (e.button !== 0) return;
    pan.current = { startX: e.clientX, startY: e.clientY, baseX: viewRef.current.x, baseY: viewRef.current.y, moved: false };
  };
  const onPointerMove = (e: React.PointerEvent) => {
    const p = pan.current;
    if (!p) return;
    const dx = e.clientX - p.startX;
    const dy = e.clientY - p.startY;
    if (!p.moved && Math.hypot(dx, dy) < DRAG_SLOP) return;
    if (!p.moved) {
      p.moved = true;
      setPanning(true);
      e.currentTarget.setPointerCapture(e.pointerId);
    }
    setView((v) => ({ ...v, x: p.baseX + dx, y: p.baseY + dy }));
  };
  const onPointerUp = (e: React.PointerEvent) => {
    const p = pan.current;
    pan.current = null;
    if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId);
    setPanning(false);
    if (!p || p.moved || e.type === 'pointercancel') return;
    // A press that did not move is a click: select the node under it, or clear.
    const id = nodeIdAt(e.target);
    onSelectRef.current?.(id && selectable?.has(id) ? id : null);
  };
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      onSelectRef.current?.(null);
      return;
    }
    if (e.key !== 'Enter' && e.key !== ' ') return;
    const id = nodeIdAt(e.target);
    if (id && selectable?.has(id)) {
      e.preventDefault();
      onSelectRef.current?.(id);
    }
  };
  // Tabbing to a node off screen brings it into view. The stage clips rather
  // than scrolls, so undo any scroll the browser does for focus and pan
  // instead.
  const onFocus = (e: React.FocusEvent) => {
    const id = nodeIdAt(e.target);
    const n = id ? layoutRef.current?.nodes.find((x) => x.id === id) : undefined;
    const stage = stageRef.current;
    if (!n || !stage) return;
    const rect = stage.getBoundingClientRect();
    const { s, x, y } = viewRef.current;
    const left = x + (n.x - n.width / 2) * s;
    const right = x + (n.x + n.width / 2) * s;
    const top = y + (n.y - n.height / 2) * s;
    const bottom = y + (n.y + n.height / 2) * s;
    const margin = 16;
    if (left < margin || top < margin || right > rect.width - margin || bottom > rect.height - margin) {
      setView({ s, x: rect.width / 2 - n.x * s, y: rect.height / 2 - n.y * s });
    }
  };
  const onScroll = (e: React.UIEvent<HTMLDivElement>) => {
    e.currentTarget.scrollTop = 0;
    e.currentTarget.scrollLeft = 0;
  };

  /**
   * The drawing as a standalone SVG file: a copy of what is on screen, with a
   * white background and without the page's accessibility and styling hooks.
   */
  const exportSvg = (): { xml: string; width: number; height: number } | null => {
    const svg = svgRef.current;
    const l = layoutRef.current;
    if (!svg || !l) return null;
    const clone = svg.cloneNode(true) as SVGSVGElement;
    for (const el of [clone, ...Array.from(clone.querySelectorAll('*'))]) {
      for (const a of Array.from(el.attributes)) {
        if (['tabindex', 'role', 'class', 'style'].includes(a.name) || a.name.startsWith('aria-') || a.name.startsWith('data-')) {
          el.removeAttribute(a.name);
        }
      }
    }
    const bg = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    bg.setAttribute('width', String(l.width));
    bg.setAttribute('height', String(l.height));
    bg.setAttribute('fill', '#ffffff');
    clone.insertBefore(bg, clone.firstChild);
    return { xml: `<?xml version="1.0" encoding="UTF-8"?>\n${new XMLSerializer().serializeToString(clone)}`, width: l.width, height: l.height };
  };
  const save = (blob: Blob, name: string) => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  const downloadSvg = () => {
    try {
      const out = exportSvg();
      if (out) save(new Blob([out.xml], { type: 'image/svg+xml;charset=utf-8' }), `${fileName}.svg`);
    } catch (err) {
      console.error('[switchboard] SVG export failed:', err);
      setError('The SVG could not be created.');
    }
  };
  const downloadPng = async () => {
    const out = (() => {
      try {
        return exportSvg();
      } catch (err) {
        console.error('[switchboard] PNG export failed:', err);
        return null;
      }
    })();
    if (!out) {
      setError('The PNG could not be created.');
      return;
    }
    const k = Math.min(2, Math.sqrt(MAX_PNG_PIXELS / (out.width * out.height)), 16_000 / Math.max(out.width, out.height));
    const url = URL.createObjectURL(new Blob([out.xml], { type: 'image/svg+xml;charset=utf-8' }));
    try {
      const blob = await new Promise<Blob>((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          canvas.width = Math.max(1, Math.round(out.width * k));
          canvas.height = Math.max(1, Math.round(out.height * k));
          const ctx = canvas.getContext('2d');
          if (!ctx) return reject(new Error('no 2D context'));
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('canvas produced no image'))), 'image/png');
        };
        img.onerror = () => reject(new Error('the diagram could not be converted'));
        img.src = url;
      });
      save(blob, `${fileName}.png`);
    } catch (err) {
      console.error('[switchboard] PNG export failed:', err);
      setError('The PNG could not be created. Try the SVG download.');
    } finally {
      URL.revokeObjectURL(url);
    }
  };
  const toggleFullscreen = () => {
    if (document.fullscreenElement) void document.exitFullscreen().catch(() => undefined);
    else void wrapperRef.current?.requestFullscreen().catch(() => undefined);
  };

  // The plain div is what goes full screen: host kit components are not
  // guaranteed to forward refs.
  return (
    <div ref={wrapperRef} style={{ display: 'flex', flex: 1, minWidth: 0, minHeight: 420 }}>
      <Box
        sx={{
          position: 'relative',
          display: 'flex',
          flexDirection: 'column',
          flex: 1,
          minWidth: 0,
          border: 1,
          borderColor: 'divider',
          borderRadius: fullscreen ? 0 : 2,
          overflow: 'hidden',
          bgcolor: 'background.paper',
        }}
      >
        <Box
          role="toolbar"
          aria-label="Diagram"
          sx={{ display: 'flex', alignItems: 'center', gap: 0.5, px: 1, py: 0.5, borderBottom: 1, borderColor: 'divider', flexShrink: 0 }}
        >
          <ActionIcon icon="lucide:zoom-out" label="Zoom out" onClick={() => zoomCentre(1 / ZOOM_STEP)} disabled={!layout} />
          <Typography variant="caption" color="text.secondary" sx={{ minWidth: 44, textAlign: 'center', fontFamily: 'monospace' }} aria-live="polite">
            {Math.round(view.s * 100)}%
          </Typography>
          <ActionIcon icon="lucide:zoom-in" label="Zoom in" onClick={() => zoomCentre(ZOOM_STEP)} disabled={!layout} />
          <ActionIcon icon="lucide:scan" label="Fit to view" onClick={fitToView} disabled={!layout} />
          <Box sx={{ flex: 1 }} />
          <SmallButton icon="lucide:image" label="PNG" variant="text" color="inherit" disabled={!layout} onClick={() => void downloadPng()} title="Download as PNG" />
          <SmallButton icon="lucide:download" label="SVG" variant="text" color="inherit" disabled={!layout} onClick={downloadSvg} title="Download as SVG" />
          <ActionIcon icon={fullscreen ? 'lucide:minimize-2' : 'lucide:maximize-2'} label={fullscreen ? 'Exit full screen' : 'Full screen'} onClick={toggleFullscreen} />
        </Box>

        {error ? (
          <Box sx={{ p: 1.5, flexShrink: 0 }}>
            <Alert severity="error" onClose={() => setError(null)}>
              {error}
            </Alert>
          </Box>
        ) : null}

        <div
          ref={stageRef}
          role="presentation"
          className="cf-stage"
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerCancel={onPointerUp}
          onKeyDown={onKeyDown}
          onFocus={onFocus}
          onScroll={onScroll}
          style={{
            position: 'relative',
            flex: 1,
            minHeight: 360,
            overflow: 'hidden',
            cursor: panning ? 'grabbing' : 'grab',
            colorScheme: 'light',
            background: '#ffffff',
            backgroundImage: 'radial-gradient(#d9dde4 1px, transparent 1px)',
            backgroundSize: '16px 16px',
            touchAction: 'none',
          }}
        >
          <style>{`
            .cf-stage .cf-selectable { cursor: pointer; }
            .cf-stage .cf-selectable:focus { outline: none; }
            .cf-stage .cf-selectable:hover .cf-shape { stroke: ${SELECTED}; stroke-width: 2px; }
            .cf-stage .cf-selectable:focus-visible .cf-shape { stroke: ${SELECTED}; stroke-width: 3px; stroke-dasharray: 6 3; }
            .cf-stage .cf-selected .cf-shape,
            .cf-stage .cf-selected:focus-visible .cf-shape { stroke: ${SELECTED}; stroke-width: 3px; stroke-dasharray: none; }
          `}</style>
          {!layout && !error ? (
            <Typography variant="body2" sx={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center', color: '#555d6b' }}>
              Drawing the diagram...
            </Typography>
          ) : null}
          {layout ? (
            <div
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                transformOrigin: '0 0',
                userSelect: 'none',
                transform: `translate(${view.x}px, ${view.y}px) scale(${view.s})`,
                transition: panning ? 'none' : 'transform 80ms ease-out',
              }}
            >
              <Diagram
                svgRef={svgRef}
                uid={uid}
                layout={layout}
                inactiveEdgeIds={inactiveEdgeIds}
                selectable={selectable}
                labels={labels}
                selectedId={selectedId ?? null}
              />
            </div>
          ) : null}
          {overlay ? (
            <div
              onPointerDown={(e) => e.stopPropagation()}
              onPointerUp={(e) => e.stopPropagation()}
              style={{ position: 'absolute', top: 12, right: 12, width: 300, maxWidth: 'calc(100% - 24px)', cursor: 'auto', colorScheme: 'normal' }}
            >
              {overlay}
            </div>
          ) : null}
        </div>
      </Box>
    </div>
  );
}

interface DiagramProps {
  svgRef: React.RefObject<SVGSVGElement | null>;
  uid: string;
  layout: Layout;
  inactiveEdgeIds?: ReadonlySet<string>;
  selectable?: ReadonlySet<string>;
  labels?: ReadonlyMap<string, string>;
  selectedId: string | null;
}

/** The SVG itself. Memoised so panning and zooming do not redraw it. */
const Diagram = memo(function Diagram({ svgRef, uid, layout, inactiveEdgeIds, selectable, labels, selectedId }: DiagramProps) {
  const isInactive = (e: LaidOutEdge) => !!inactiveEdgeIds?.has(e.id);
  // Greyed-out routes underneath, so the routes in effect read on top.
  const edges = [...layout.edges].sort((a, b) => Number(isInactive(b)) - Number(isInactive(a)));
  return (
    <svg
      ref={svgRef}
      width={layout.width}
      height={layout.height}
      viewBox={`0 0 ${layout.width} ${layout.height}`}
      fontFamily={FONT_FAMILY}
      role="group"
      aria-label="Call flow diagram"
      style={{ display: 'block', overflow: 'visible' }}
    >
      <defs>
        <marker id={`${uid}-arrow`} viewBox="0 0 10 10" refX="9" refY="5" markerUnits="userSpaceOnUse" markerWidth="10" markerHeight="10" orient="auto">
          <path d="M0,0L10,5L0,10z" fill={STROKE} />
        </marker>
        <marker id={`${uid}-arrow-dim`} viewBox="0 0 10 10" refX="9" refY="5" markerUnits="userSpaceOnUse" markerWidth="10" markerHeight="10" orient="auto">
          <path d="M0,0L10,5L0,10z" fill={DIM} />
        </marker>
      </defs>
      {layout.groups.map((g) => (
        <GroupBox key={g.id} g={g} />
      ))}
      {edges.map((e) => (
        <EdgePath key={e.id} e={e} inactive={isInactive(e)} uid={uid} />
      ))}
      {edges.map((e) => (e.label ? <EdgeLabel key={e.id} e={e} inactive={isInactive(e)} /> : null))}
      {layout.groups.map((g) => (g.title ? <GroupTitle key={g.id} g={g} /> : null))}
      {layout.nodes.map((n) => (
        <NodeBox
          key={n.id}
          n={n}
          selectable={!!selectable?.has(n.id)}
          selected={n.id === selectedId}
          label={labels?.get(n.id) ?? n.lines.join(' ')}
        />
      ))}
    </svg>
  );
});

const GROUP_FILL = '#f7f7f9';

function GroupBox({ g }: { g: LaidOutGroup }) {
  return <rect x={g.x} y={g.y} width={g.width} height={g.height} rx={8} fill={GROUP_FILL} stroke="#b8bcc6" strokeDasharray="4 3" />;
}

/** Drawn over the routes, on the group's own colour, so a route entering the box passes behind it. */
function GroupTitle({ g }: { g: LaidOutGroup }) {
  const width = measureText(g.title, GROUP_FONT) + 8;
  return (
    <g>
      <rect x={g.x + GROUP_PAD - 4} y={g.y + 5} width={width} height={17} rx={3} fill={GROUP_FILL} />
      <text x={g.x + GROUP_PAD} y={g.y + 18} fontSize={12} fontWeight={700} fill="#4b5563">
        {g.title}
      </text>
    </g>
  );
}

function EdgePath({ e, inactive, uid }: { e: LaidOutEdge; inactive: boolean; uid: string }) {
  return (
    <path
      d={basisPath(e.points)}
      fill="none"
      stroke={inactive ? DIM : STROKE}
      strokeWidth={1.5}
      strokeDasharray={inactive ? '4 4' : undefined}
      opacity={inactive ? 0.75 : 1}
      markerEnd={`url(#${uid}-arrow${inactive ? '-dim' : ''})`}
      data-edge-id={e.id}
      data-inactive={inactive ? 'true' : undefined}
    />
  );
}

function EdgeLabel({ e, inactive }: { e: LaidOutEdge; inactive: boolean }) {
  const l = e.label!;
  return (
    <g transform={`translate(${l.x - l.width / 2},${l.y - l.height / 2})`}>
      <rect width={l.width} height={l.height} rx={3} fill="#ffffff" fillOpacity={0.92} />
      <text textAnchor="middle" fontSize={12} fill={inactive ? '#8b919c' : STROKE}>
        {l.lines.map((line, i) => (
          <tspan key={i} x={l.width / 2} y={2 + i * EDGE_LINE + EDGE_LINE / 2 + 4}>
            {line}
          </tspan>
        ))}
      </text>
    </g>
  );
}

function NodeBox({ n, selectable, selected, label }: { n: LaidOutNode; selectable: boolean; selected: boolean; label: string }) {
  const cx = n.width / 2;
  const centreY = n.height / 2 + (n.shape === 'cylinder' ? 4 : 0);
  const top = centreY - (n.lines.length * NODE_LINE) / 2;
  const className = ['cf-node', selectable ? 'cf-selectable' : '', selected ? 'cf-selected' : ''].filter(Boolean).join(' ');
  return (
    <g
      transform={`translate(${n.x - n.width / 2},${n.y - n.height / 2})`}
      className={className}
      data-node-id={n.id}
      {...(selectable ? { role: 'button', tabIndex: 0, 'aria-label': label, 'aria-pressed': selected } : {})}
    >
      <Shape n={n} />
      <text textAnchor="middle" fontSize={14} fill={n.text}>
        {n.lines.map((line, i) => (
          <tspan key={i} x={cx} y={top + i * NODE_LINE + NODE_LINE / 2 + 5}>
            {line}
          </tspan>
        ))}
      </text>
    </g>
  );
}

function Shape({ n }: { n: LaidOutNode }) {
  const { width: w, height: h, fill } = n;
  const common = { className: 'cf-shape', fill, stroke: STROKE, strokeWidth: 1 };
  switch (n.shape) {
    case 'stadium':
      return <rect {...common} width={w} height={h} rx={h / 2} />;
    case 'hexagon':
      return <polygon {...common} points={`${HEX_INSET},0 ${w - HEX_INSET},0 ${w},${h / 2} ${w - HEX_INSET},${h} ${HEX_INSET},${h} 0,${h / 2}`} />;
    case 'subroutine':
      return (
        <g>
          <rect {...common} width={w} height={h} />
          <path d={`M8,0V${h}M${w - 8},0V${h}`} stroke={STROKE} strokeWidth={1} fill="none" />
        </g>
      );
    case 'cylinder': {
      const ry = 8;
      const body = h - ry * 2;
      return <path {...common} d={`M0,${ry}a${w / 2},${ry} 0 0,0 ${w},0a${w / 2},${ry} 0 0,0 ${-w},0l0,${body}a${w / 2},${ry} 0 0,0 ${w},0l0,${-body}`} />;
    }
    case 'circle':
      return <circle {...common} cx={w / 2} cy={h / 2} r={w / 2} />;
    default:
      return <rect {...common} width={w} height={h} rx={4} />;
  }
}
