/**
 * Lays a call-flow graph out for drawing, with dagre: the same layered layout
 * engine Mermaid runs for flowcharts, used directly.
 *
 * Why not Mermaid itself (what Engage renders with): the whole library is about
 * 4 MB of JavaScript and 14 MB of source maps in 70-odd files, and Horizon's
 * bundle analysis caps an app at 40 chunk files and 8 MB (analysis-settings
 * max_chunk_count / max_total_bytes). Dagre is about 64 KB. Drawing the SVG
 * ourselves also means plain SVG text (so PNG export works in Chrome, which
 * refuses to export Mermaid's HTML labels from a canvas) and real buttons for
 * the clickable nodes.
 *
 * The look follows Engage's Mermaid adapter: top-down, the same node colours
 * and shapes per type, edge labels, a box around grouped nodes (a queue under
 * its queue user), and time-simulator dimming for inactive routes.
 */
import dagre from '@dagrejs/dagre';

import type { CallFlowGraph, CallFlowNode, CallFlowNodeType } from './graph';

export interface Point {
  x: number;
  y: number;
}

export type NodeShape = 'stadium' | 'rect' | 'hexagon' | 'subroutine' | 'cylinder' | 'circle';

export interface LaidOutNode {
  id: string;
  node: CallFlowNode;
  shape: NodeShape;
  fill: string;
  text: string;
  lines: string[];
  /** Centre. */
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface LaidOutEdge {
  id: string;
  source: string;
  target: string;
  points: Point[];
  label: { lines: string[]; x: number; y: number; width: number; height: number } | null;
  inactive: boolean;
}

export interface LaidOutGroup {
  id: string;
  title: string;
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface Layout {
  width: number;
  height: number;
  nodes: LaidOutNode[];
  edges: LaidOutEdge[];
  groups: LaidOutGroup[];
}

/** Width in px of `text` drawn in `font` (a canvas `font` string). */
export type Measure = (text: string, font: string) => number;

export const FONT_FAMILY = 'Arial, Helvetica, sans-serif';
export const NODE_FONT = `14px ${FONT_FAMILY}`;
export const EDGE_FONT = `12px ${FONT_FAMILY}`;
export const NODE_LINE = 18;
export const EDGE_LINE = 15;
export const GROUP_FONT = `bold 12px ${FONT_FAMILY}`;
/** How far a hexagon's side points stick out past its text box. */
export const HEX_INSET = 14;
/** Padding added around dagre's box for a group, and the title's inset. */
export const GROUP_PAD = 10;
/** Space above a group's members for its title. */
export const GROUP_TITLE_SPACE = 28;
const NODE_MAX_TEXT = 200;
const EDGE_MAX_TEXT = 150;
const PAD_X = 14;
const PAD_Y = 9;

/** Engage's Mermaid classDefs, one colour per node type. */
export const STYLE_BY_TYPE: Record<CallFlowNodeType, { shape: NodeShape; fill: string; text: string }> = {
  ingress: { shape: 'stadium', fill: '#E0E0E0', text: '#000000' },
  user: { shape: 'rect', fill: '#ADD8E6', text: '#000000' },
  auto_attendant: { shape: 'hexagon', fill: '#FFD700', text: '#000000' },
  call_queue: { shape: 'subroutine', fill: '#FFA500', text: '#000000' },
  voicemail: { shape: 'cylinder', fill: '#A9A9A9', text: '#000000' },
  offnet: { shape: 'rect', fill: '#90EE90', text: '#000000' },
  hangup: { shape: 'circle', fill: '#FF6347', text: '#FFFFFF' },
  conference: { shape: 'hexagon', fill: '#EE82EE', text: '#000000' },
  directory: { shape: 'rect', fill: '#DA70D6', text: '#000000' },
  device: { shape: 'rect', fill: '#D8BFD8', text: '#000000' },
  other: { shape: 'rect', fill: '#D3D3D3', text: '#000000' },
};

/** Split explicit lines, then wrap each at word boundaries to `max` px. */
export function wrapText(text: string, font: string, max: number, measure: Measure): string[] {
  const out: string[] = [];
  for (const raw of String(text ?? '').split(/\n/)) {
    const words = raw.trim().split(/\s+/).filter(Boolean);
    if (!words.length) continue;
    let line = '';
    for (const w of words) {
      const next = line ? `${line} ${w}` : w;
      if (line && measure(next, font) > max) {
        out.push(line);
        line = w;
      } else {
        line = next;
      }
    }
    if (line) out.push(line);
  }
  return out.length ? out : [''];
}

/** `text` on one line, cut with an ellipsis to fit `max` px. */
export function fitLine(text: string, font: string, max: number, measure: Measure): string {
  const t = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (measure(t, font) <= max) return t;
  let lo = 0;
  let hi = t.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (measure(`${t.slice(0, mid).trimEnd()}\u2026`, font) <= max) lo = mid;
    else hi = mid - 1;
  }
  return lo ? `${t.slice(0, lo).trimEnd()}\u2026` : '';
}

function nodeBox(shape: NodeShape, lines: string[], measure: Measure): { width: number; height: number } {
  const textW = Math.max(...lines.map((l) => measure(l, NODE_FONT)), 20);
  const textH = lines.length * NODE_LINE;
  let width = textW + PAD_X * 2;
  let height = textH + PAD_Y * 2;
  switch (shape) {
    case 'stadium':
      width += height / 2;
      break;
    case 'hexagon':
      width += HEX_INSET * 2;
      break;
    case 'subroutine':
      width += 16;
      break;
    case 'cylinder':
      height += 16;
      break;
    case 'circle': {
      const d = Math.max(width, height);
      width = d;
      height = d;
      break;
    }
    default:
      break;
  }
  return { width: Math.ceil(width), height: Math.ceil(height) };
}

export function layoutGraph(
  graph: CallFlowGraph,
  opts: { measure: Measure; inactiveEdgeIds?: ReadonlySet<string> },
): Layout {
  const { measure } = opts;
  const g = new dagre.graphlib.Graph({ multigraph: true, compound: true });
  g.setGraph({ rankdir: 'TB', nodesep: 36, ranksep: 64, edgesep: 16, marginx: 24, marginy: 32 });
  g.setDefaultEdgeLabel(() => ({}));

  const byId = new Map(graph.nodes.map((n) => [n.id, n]));
  const prepared = new Map<string, { shape: NodeShape; fill: string; text: string; lines: string[] }>();
  for (const n of graph.nodes) {
    const style = STYLE_BY_TYPE[n.type] ?? STYLE_BY_TYPE.other;
    const lines = wrapText(n.label, NODE_FONT, NODE_MAX_TEXT, measure);
    prepared.set(n.id, { ...style, lines });
    g.setNode(n.id, nodeBox(style.shape, lines, measure));
  }

  // A node with a parent that is itself on the graph sits in a group titled
  // with the parent's label (Engage's Mermaid `subgraph <parent>_group`).
  const groupTitles = new Map<string, string>();
  for (const n of graph.nodes) {
    const parent = n.parent ? byId.get(n.parent) : undefined;
    if (!parent) continue;
    const gid = `group:${parent.id}`;
    if (!groupTitles.has(gid)) {
      groupTitles.set(gid, parent.label.split('\n')[0]);
      g.setNode(gid, {});
    }
    g.setParent(n.id, gid);
  }

  for (const e of graph.edges) {
    if (!byId.has(e.source) || !byId.has(e.target)) continue;
    const lines = e.label ? wrapText(e.label, EDGE_FONT, EDGE_MAX_TEXT, measure) : [];
    const width = lines.length ? Math.ceil(Math.max(...lines.map((l) => measure(l, EDGE_FONT)))) + 8 : 0;
    const height = lines.length ? lines.length * EDGE_LINE + 4 : 0;
    g.setEdge(e.source, e.target, { width, height, labelpos: 'c', lines }, e.id);
  }

  dagre.layout(g);

  const nodes: LaidOutNode[] = graph.nodes.map((n) => {
    const box = g.node(n.id) as { x: number; y: number; width: number; height: number };
    const p = prepared.get(n.id)!;
    return { id: n.id, node: n, shape: p.shape, fill: p.fill, text: p.text, lines: p.lines, x: box.x, y: box.y, width: box.width, height: box.height };
  });

  const nodeById = new Map(nodes.map((n) => [n.id, n]));
  const edges: LaidOutEdge[] = [];
  for (const e of graph.edges) {
    const le = g.edge({ v: e.source, w: e.target, name: e.id }) as { points?: Point[]; x?: number; y?: number; width?: number; height?: number; lines?: string[] } | undefined;
    if (!le?.points?.length) continue;
    let points = le.points.map((pt) => ({ x: pt.x, y: pt.y }));
    const self = e.source === e.target ? nodeById.get(e.source) : undefined;
    if (self) {
      // Dagre's loop for a route back to its own node (a menu's "Invalid
      // Input: repeat") floats beside the node; start and end it on the node's
      // right side, out to where dagre left room (its label sits there).
      const x = self.x + self.width / 2;
      const dx = Math.max(24, (le.x ?? x + 24) - x);
      const dy = self.height / 2;
      const edge = rightOutlineAt(self, dy / 2);
      points = [
        { x: edge, y: self.y - dy / 2 },
        { x: x + (2 * dx) / 3, y: self.y - dy },
        { x: x + dx, y: self.y },
        { x: x + (2 * dx) / 3, y: self.y + dy },
        { x: edge, y: self.y + dy / 2 },
      ];
    } else if (points.length >= 2) {
      // Dagre ends edges on the node's bounding box; bring them in to the drawn
      // outline where that differs (circles, hexagons), as Mermaid does.
      const from = nodeById.get(e.source);
      const to = nodeById.get(e.target);
      const start = from && clipToShape(from, points[1]);
      const end = to && clipToShape(to, points[points.length - 2]);
      if (start) points[0] = start;
      if (end) points[points.length - 1] = end;
    }
    edges.push({
      id: e.id,
      source: e.source,
      target: e.target,
      points,
      label:
        le.lines && le.lines.length && le.x != null && le.y != null
          ? { lines: le.lines, x: le.x, y: le.y, width: le.width ?? 0, height: le.height ?? 0 }
          : null,
      inactive: !!opts.inactiveEdgeIds?.has(e.id),
    });
  }

  // Each group's box: dagre's width, but its height hugs the members, with
  // room above them for the title (dagre leaves half a rank of space above
  // and below a cluster, and the space below read as a gap).
  const groups: LaidOutGroup[] = [];
  for (const [gid, title] of groupTitles) {
    const box = g.node(gid) as { x?: number; y?: number; width?: number; height?: number } | undefined;
    if (!box || box.x == null || box.y == null || !box.width || !box.height) continue;
    const members = nodes.filter((n) => g.parent(n.id) === gid);
    if (!members.length) continue;
    const top = Math.min(...members.map((n) => n.y - n.height / 2)) - GROUP_TITLE_SPACE;
    const bottom = Math.max(...members.map((n) => n.y + n.height / 2)) + GROUP_PAD;
    const width = box.width + GROUP_PAD * 2;
    groups.push({
      id: gid,
      title: fitLine(title, GROUP_FONT, width - GROUP_PAD * 2, measure),
      x: box.x - box.width / 2 - GROUP_PAD,
      y: top,
      width,
      height: bottom - top,
    });
  }

  const label = g.graph() as { width?: number; height?: number };
  return { width: Math.ceil(label.width ?? 0), height: Math.ceil(label.height ?? 0), nodes, edges, groups };
}

/**
 * Where the line from a node's centre towards `outside` crosses the node's
 * outline, for the shapes whose outline is not their bounding box. Null means
 * the bounding box is right (dagre's point stands).
 */
export function clipToShape(n: Pick<LaidOutNode, 'shape' | 'x' | 'y' | 'width' | 'height'>, outside: Point): Point | null {
  const dx = outside.x - n.x;
  const dy = outside.y - n.y;
  if (!dx && !dy) return null;
  if (n.shape === 'circle') {
    const k = n.width / 2 / Math.hypot(dx, dy);
    return { x: n.x + dx * k, y: n.y + dy * k };
  }
  if (n.shape !== 'hexagon') return null;
  const w = n.width / 2;
  const h = n.height / 2;
  const poly: Array<[number, number]> = [
    [-w + HEX_INSET, -h],
    [w - HEX_INSET, -h],
    [w, 0],
    [w - HEX_INSET, h],
    [-w + HEX_INSET, h],
    [-w, 0],
  ];
  let best = Infinity;
  for (let i = 0; i < poly.length; i++) {
    const [x1, y1] = poly[i];
    const [x2, y2] = poly[(i + 1) % poly.length];
    const ex = x2 - x1;
    const ey = y2 - y1;
    const den = dx * ey - dy * ex;
    if (Math.abs(den) < 1e-9) continue;
    const t = (x1 * ey - y1 * ex) / den;
    const u = (x1 * dy - y1 * dx) / den;
    if (t > 0 && u >= -1e-9 && u <= 1 + 1e-9) best = Math.min(best, t);
  }
  return Number.isFinite(best) ? { x: n.x + dx * best, y: n.y + dy * best } : null;
}

/** The x of a node's right-hand outline, `t` px above or below its centre. */
export function rightOutlineAt(n: Pick<LaidOutNode, 'shape' | 'x' | 'width' | 'height'>, t: number): number {
  const right = n.x + n.width / 2;
  const h = n.height / 2;
  const off = Math.min(Math.abs(t), h);
  switch (n.shape) {
    case 'hexagon':
      return right - (HEX_INSET * off) / h;
    case 'circle': {
      const r = n.width / 2;
      return n.x + Math.sqrt(Math.max(0, r * r - off * off));
    }
    case 'stadium':
      return right - h + Math.sqrt(Math.max(0, h * h - off * off));
    default:
      return right;
  }
}

/**
 * An SVG path through dagre's edge points, smoothed the way Mermaid draws
 * (d3's curveBasis, reproduced here to keep d3 out of the bundle).
 */
export function basisPath(pts: Point[]): string {
  if (!pts.length) return '';
  if (pts.length === 1) return `M${pts[0].x},${pts[0].y}`;
  const f = (v: number) => Math.round(v * 10) / 10;
  let d = '';
  let x0 = 0;
  let y0 = 0;
  let x1 = 0;
  let y1 = 0;
  let state = 0;
  const bezier = (x: number, y: number) => {
    d += `C${f((2 * x0 + x1) / 3)},${f((2 * y0 + y1) / 3)},${f((x0 + 2 * x1) / 3)},${f((y0 + 2 * y1) / 3)},${f((x0 + 4 * x1 + x) / 6)},${f((y0 + 4 * y1 + y) / 6)}`;
  };
  for (const { x, y } of pts) {
    if (state === 0) {
      d += `M${f(x)},${f(y)}`;
      state = 1;
    } else if (state === 1) {
      state = 2;
    } else {
      if (state === 2) {
        d += `L${f((5 * x0 + x1) / 6)},${f((5 * y0 + y1) / 6)}`;
        state = 3;
      }
      bezier(x, y);
    }
    x0 = x1;
    x1 = x;
    y0 = y1;
    y1 = y;
  }
  if (state === 3) {
    bezier(x1, y1);
    d += `L${f(x1)},${f(y1)}`;
  } else if (state === 2) {
    d += `L${f(x1)},${f(y1)}`;
  }
  return d;
}
