/**
 * The crawler's six NetSapiens reads, made through the host API proxy.
 *
 * A crawl is a long walk: one read per user, auto-attendant prompt and queue it
 * reaches, one at a time. The proxy allows an app about 100 requests a minute,
 * so this paces itself instead of failing halfway through a domain:
 *
 *   - a sliding window of `perMinute` requests (default 80, leaving headroom
 *     for another tab of the same app sharing the budget), waiting for a free
 *     slot rather than refusing;
 *   - a 429 anyway (that other tab) waits BACKOFF_MS and retries, up to
 *     MAX_RETRIES times;
 *   - an aborted crawl (the domain changed, the page closed) stops sending: every
 *     later read fails at once, the crawler records it as a warning and the
 *     page discards the result.
 *
 * `onWait` tells the page when it is waiting, so the progress line can say why
 * it paused instead of looking stuck.
 */
import type { HorizonApiClient } from '@netsapiens/horizon-sdk';

import { isRateLimitError } from '../api/budget';
import { classifyError, describeError } from '../model/errors';
import type { CallFlowClient } from './graph';

const WINDOW_MS = 60_000;
export const DEFAULT_PER_MINUTE = 80;
export const BACKOFF_MS = 15_000;
const MAX_RETRIES = 3;
const e = encodeURIComponent;

export class CrawlCancelled extends Error {
  constructor() {
    super('cancelled');
    this.name = 'CrawlCancelled';
  }
}

export interface CrawlClientOptions {
  perMinute?: number;
  signal?: AbortSignal;
  /** Called with the time the crawl resumes, then with null once it has. */
  onWait?: (resumesAt: number | null) => void;
  /** Injected in tests. */
  now?: () => number;
  sleep?: (ms: number) => Promise<void>;
}

export interface CrawlClient extends CallFlowClient {
  /** Reads sent so far (retries included). */
  requests(): number;
}

/**
 * Short, operator-facing reason for a failed read. The crawler prefixes it with
 * what it was reading ("Failed to fetch auto-attendant 9001/Prompt_900101: ...").
 */
export function readReason(err: unknown): string {
  if (err instanceof CrawlCancelled) return 'cancelled';
  switch (classifyError(err)) {
    case 'not-found':
      return 'not found on the phone system';
    case 'scope':
      return 'your NetSapiens account is not permitted to read it';
    case 'rate':
      return 'Horizon kept limiting requests';
    default:
      return describeError(err).replace(/\.$/, '');
  }
}

/** Single-record reads sometimes arrive wrapped in a one-element array. */
function one(v: unknown): unknown {
  return Array.isArray(v) ? (v[0] ?? null) : v;
}

/** List reads sometimes arrive wrapped as `{ data: [...] }` or `{ items: [...] }`. */
function many(v: unknown): unknown {
  if (Array.isArray(v) || !v || typeof v !== 'object') return v;
  const o = v as { data?: unknown; items?: unknown };
  if (Array.isArray(o.data)) return o.data;
  if (Array.isArray(o.items)) return o.items;
  return v;
}

export function createCrawlClient(api: HorizonApiClient, opts: CrawlClientOptions = {}): CrawlClient {
  const perMinute = Math.max(1, opts.perMinute ?? DEFAULT_PER_MINUTE);
  const now = opts.now ?? (() => Date.now());
  const sleep = opts.sleep ?? ((ms: number) => new Promise<void>((r) => setTimeout(r, ms)));
  const stamps: number[] = [];
  let sent = 0;

  const checkAbort = () => {
    if (opts.signal?.aborted) throw new CrawlCancelled();
  };

  async function wait(ms: number): Promise<void> {
    opts.onWait?.(now() + ms);
    try {
      await sleep(ms);
    } finally {
      opts.onWait?.(null);
    }
    checkAbort();
  }

  /** Take a slot in the sliding window, waiting for the oldest to expire if full. */
  async function slot(): Promise<void> {
    for (;;) {
      checkAbort();
      const t = now();
      while (stamps.length && stamps[0] <= t - WINDOW_MS) stamps.shift();
      if (stamps.length < perMinute) {
        stamps.push(t);
        return;
      }
      await wait(stamps[0] + WINDOW_MS - t + 50);
    }
  }

  async function get(path: string, params?: Record<string, unknown>): Promise<unknown> {
    for (let attempt = 0; ; attempt++) {
      await slot();
      sent++;
      try {
        return await api.get<unknown>(path, params);
      } catch (err) {
        if (!isRateLimitError(err) || attempt >= MAX_RETRIES) throw new Error(readReason(err));
        await wait(BACKOFF_MS);
      }
    }
  }

  const page = (p: { limit: number; start: number }) => ({ limit: p.limit, start: p.start });

  return {
    requests: () => sent,
    users: {
      list: async (d, p) => many(await get(`/domains/${e(d)}/users`, page(p))),
      get: async (d, u) => one(await get(`/domains/${e(d)}/users/${e(u)}`)),
    },
    phoneNumbers: {
      listForDomain: async (d, p) => many(await get(`/domains/${e(d)}/phonenumbers`, page(p))),
    },
    autoAttendant: {
      get: async (d, u, prompt) => one(await get(`/domains/${e(d)}/users/${e(u)}/autoattendants/${e(prompt)}`)),
    },
    answerRules: {
      list: async (d, u) => many(await get(`/domains/${e(d)}/users/${e(u)}/answerrules`)),
    },
    callCenter: {
      listAgents: async (d, q) => many(await get(`/domains/${e(d)}/callqueues/${e(q)}/agents`)),
    },
  };
}
