/**
 * Call Flow - the app's second page (/apps/call-flow for the original install).
 *
 * Draws where every phone number in a domain goes: number -> answer rules ->
 * users, auto attendants and their menu options, queues and their agents,
 * voicemail, off-net numbers. Ported from the Engage portal's Call Flow page;
 * the crawl, the time simulator and the diagram are the same code (see
 * callflow/graph.ts), so both tools draw the same graph for the same domain.
 *
 * What is different in Horizon:
 *   - reads go through the host API proxy, paced to its request limit
 *     (callflow/client.ts), so a large domain takes longer and says why;
 *   - the domain picker is the switchboard's, and the pick is shared with it;
 *   - clicking a user or a queue opens it in the Virtual Switchboard's panel;
 *   - a finished crawl is kept for ten minutes, so going to the switchboard and
 *     back does not walk the whole domain again (Refresh always does).
 */
import type * as React from 'react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useHorizonContext } from '@netsapiens/horizon-sdk';

import type { ZoneMarkerProps } from '../App';
import { DomainPicker, useDomainChoice } from '../data/domainChoice';
import { isBoolean, usePersistentState } from '../data/persist';
import { leaveHandoff } from '../data/handoff';
import { useNow } from '../data/clock';
import {
  buildCallFlowGraph,
  computeSimulation,
  filterGraphToRoots,
  type CallFlowGraph,
  type CallFlowNode,
  type CallFlowNodeType,
  type SimulationResult,
} from '../callflow/graph';
import { createCrawlClient } from '../callflow/client';
import { CallFlowViewer } from '../callflow/Viewer';
import { formatAgo, formatDateTime } from '../model/format';
import { useKit } from '../ui/kit';
import { ActionIcon, SmallButton } from '../ui/bits';

declare const __APP_ROUTE__: string;
const SWITCHBOARD_ROUTE = typeof __APP_ROUTE__ === 'string' ? __APP_ROUTE__ : 'switchboard';

const CACHE_TTL_MS = 10 * 60_000;
const built = new Map<string, { graph: CallFlowGraph; warnings: string[]; at: number }>();

const TYPE_LABEL: Record<CallFlowNodeType, string> = {
  ingress: 'Phone number',
  user: 'User',
  auto_attendant: 'Auto attendant',
  call_queue: 'Call queue',
  voicemail: 'Voicemail',
  offnet: 'Outside number',
  hangup: 'Hang up',
  conference: 'Conference',
  directory: 'Company directory',
  device: 'Device',
  other: 'Other',
};

/** Queue -> agent edges, as the crawler draws them. */
const isAgentEdge = (e: CallFlowGraph['edges'][number], byId: ReadonlyMap<string, CallFlowNode>) =>
  e.label === 'Agent' && byId.get(e.source)?.type === 'call_queue';

/** "Phone Number: (813) 555-0142" -> "(813) 555-0142". */
const didLabel = (n: CallFlowNode) => n.label.replace(/^Phone Number:\s*/, '');

/** A datetime-local input value for a Date, in local time. */
function toLocalInput(d: Date): string {
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
}

export default function CallFlowPage(marker: ZoneMarkerProps) {
  const kit = useKit();
  const { PageTemplate, Box, Stack, Typography, Alert, Paper, SearchField, Checkbox, TextField, Icon } = kit;
  const { api, navigate } = useHorizonContext();
  const { domain, multiDomain, pick } = useDomainChoice();
  const now = useNow();

  const cached = built.get(domain);
  const [graph, setGraph] = useState<CallFlowGraph | null>(cached?.graph ?? null);
  const [builtAt, setBuiltAt] = useState<number | null>(cached?.at ?? null);
  const [warnings, setWarnings] = useState<string[]>(cached?.warnings ?? []);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState<{ current: number; total: number; reads: number } | null>(null);
  const [pausedUntil, setPausedUntil] = useState<number | null>(null);

  const [search, setSearch] = useState('');
  const [roots, setRoots] = useState<Set<string>>(new Set());
  const [selectedId, setSelectedId] = useState<string | null>(null);
  // Queue rosters are the widest part of most diagrams (every agent sits on
  // one row), so by default each queue shows its agent count instead and its
  // details list them.
  const [showAgents, setShowAgents] = usePersistentState<boolean>('callflow.showAgents', false, isBoolean);

  const [simOpen, setSimOpen] = useState(false);
  const [simInput, setSimInput] = useState('');
  const [simDate, setSimDate] = useState<Date | null>(null);

  const seq = useRef(0);
  const abort = useRef<AbortController | null>(null);
  const lastAttempt = useRef<string | null>(cached ? domain : null);

  const build = useCallback(async () => {
    if (!domain) return;
    abort.current?.abort();
    const ctl = new AbortController();
    abort.current = ctl;
    const mine = ++seq.current;
    const stale = () => mine !== seq.current;
    lastAttempt.current = domain;
    setLoading(true);
    setError(null);
    setWarnings([]);
    setSelectedId(null);
    setProgress({ current: 0, total: 0, reads: 0 });
    const collected: string[] = [];
    const client = createCrawlClient(api, {
      signal: ctl.signal,
      onWait: (until) => {
        if (!stale()) setPausedUntil(until);
      },
    });
    try {
      const result = await buildCallFlowGraph(client, domain, {
        onProgress: (current, total) => {
          if (!stale()) setProgress({ current, total, reads: client.requests() });
        },
        onWarning: (w) => {
          if (!/: cancelled$/.test(w)) collected.push(w);
        },
      });
      if (stale()) return;
      const at = Date.now();
      built.set(domain, { graph: result, warnings: collected, at });
      setGraph(result);
      setBuiltAt(at);
      setRoots(new Set());
    } catch (err) {
      if (stale()) return;
      setError(err instanceof Error ? err.message : 'The call flow could not be built.');
      setGraph(null);
    } finally {
      if (!stale()) {
        setWarnings(collected);
        setLoading(false);
        setProgress(null);
        setPausedUntil(null);
      }
    }
  }, [api, domain]);

  // A new domain: show its kept crawl if fresh, otherwise walk it.
  useEffect(() => {
    if (!domain || lastAttempt.current === domain) return;
    const keep = built.get(domain);
    setRoots(new Set());
    setSelectedId(null);
    setSimDate(null);
    if (keep && Date.now() - keep.at < CACHE_TTL_MS) {
      lastAttempt.current = domain;
      setGraph(keep.graph);
      setWarnings(keep.warnings);
      setBuiltAt(keep.at);
      setError(null);
      return;
    }
    setGraph(null);
    void build();
  }, [domain, build]);

  // Leaving the page stops the crawl.
  useEffect(() => () => abort.current?.abort(), []);

  const ingress = useMemo(() => (graph?.nodes ?? []).filter((n) => n.type === 'ingress'), [graph]);
  const visibleDids = useMemo(() => {
    const q = search.trim().toLowerCase();
    return q ? ingress.filter((n) => n.label.toLowerCase().includes(q)) : ingress;
  }, [ingress, search]);
  const byId = useMemo(() => new Map((graph?.nodes ?? []).map((n) => [n.id, n])), [graph]);
  const agentsByQueue = useMemo(() => {
    const out = new Map<string, string[]>();
    for (const e of graph?.edges ?? []) {
      if (!isAgentEdge(e, byId)) continue;
      const list = out.get(e.source) ?? [];
      if (!list.includes(e.target)) list.push(e.target);
      out.set(e.source, list);
    }
    return out;
  }, [graph, byId]);
  const drawn = useMemo(() => {
    if (!graph || showAgents || !agentsByQueue.size) return graph;
    const edges = graph.edges.filter((e) => !isAgentEdge(e, byId));
    // Drop agents that only a queue led to; one that is also a destination stays.
    const kept = filterGraphToRoots({ nodes: graph.nodes, edges }, graph.nodes.filter((n) => n.type === 'ingress').map((n) => n.id));
    return {
      nodes: kept.nodes.map((n) => {
        const k = agentsByQueue.get(n.id)?.length;
        return k ? { ...n, label: `${n.label}\n${k} ${k === 1 ? 'agent' : 'agents'}` } : n;
      }),
      edges: kept.edges,
    };
  }, [graph, showAgents, agentsByQueue, byId]);
  const shown = useMemo(() => {
    if (!drawn) return null;
    return roots.size ? filterGraphToRoots(drawn, Array.from(roots)) : drawn;
  }, [drawn, roots]);
  const simulation = useMemo<SimulationResult | null>(() => (shown && simDate ? computeSimulation(shown, simDate) : null), [shown, simDate]);
  const selectable = useMemo(() => new Set((shown?.nodes ?? []).filter((n) => n.link).map((n) => n.id)), [shown]);
  // Accessible names: one line, without the diagram's own "Queue:" prefix.
  const labels = useMemo(
    () => new Map((shown?.nodes ?? []).map((n) => [n.id, `${TYPE_LABEL[n.type]}: ${n.label.replace(/^Queue:\s*/, '').replace(/\s*\n\s*/g, ', ')}`])),
    [shown],
  );
  const selected = selectedId ? byId.get(selectedId) ?? null : null;
  const selectedLines = selected ? selected.label.replace(/^Queue:\s*/, '').split(/\s*\n\s*/) : [];
  const selectedAgents = selected ? (agentsByQueue.get(selected.id) ?? []).map((id) => byId.get(id)?.label.split('\n')[0] ?? id) : [];

  const toggleRoot = (id: string) =>
    setRoots((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  const allChecked = ingress.length > 0 && roots.size === ingress.length;

  const openInSwitchboard = (node: CallFlowNode) => {
    const [kind, ext] = (node.link ?? '').split(/:(.*)/s);
    if (!ext) return;
    leaveHandoff(kind === 'queue' ? { kind: 'queue', queue: ext } : { kind: 'user', user: ext, tab: 'handling' });
    navigate(`/apps/${SWITCHBOARD_ROUTE}`);
  };

  const applySim = () => {
    const d = new Date(simInput);
    if (!simInput || Number.isNaN(d.getTime())) return;
    setSimDate(d);
    setSimOpen(false);
  };

  const pausedFor = pausedUntil ? Math.max(1, Math.ceil((pausedUntil - now) / 1000)) : 0;

  const detailsCard = selected ? (
    <Paper elevation={4} sx={{ p: 1.5 }}>
      <Stack direction="row" alignItems="flex-start" spacing={1}>
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography variant="overline" color="text.secondary" sx={{ lineHeight: 1.4 }}>
            {TYPE_LABEL[selected.type]}
          </Typography>
          <Typography variant="subtitle2" sx={{ fontWeight: 700, wordBreak: 'break-word' }}>
            {selectedLines[0]}
          </Typography>
          {selectedLines.slice(1).map((line, i) => (
            <Typography key={i} variant="body2" color="text.secondary" sx={{ wordBreak: 'break-word' }}>
              {line}
            </Typography>
          ))}
        </Box>
        <ActionIcon icon="lucide:x" label="Close details" onClick={() => setSelectedId(null)} />
      </Stack>
      {selected.details && Object.keys(selected.details).length ? (
        <Box component="dl" sx={{ m: 0, mt: 1, display: 'grid', gridTemplateColumns: 'max-content 1fr', gap: '2px 10px', fontSize: 13 }}>
          {Object.entries(selected.details).map(([k, v]) => (
            <Box key={k} sx={{ display: 'contents' }}>
              <Box component="dt" sx={{ color: 'text.secondary' }}>
                {k}
              </Box>
              <Box component="dd" sx={{ m: 0, wordBreak: 'break-word' }}>
                {String(v)}
              </Box>
            </Box>
          ))}
        </Box>
      ) : null}
      {selectedAgents.length ? (
        <Box sx={{ mt: 1 }}>
          <Typography variant="caption" color="text.secondary">
            Agents ({selectedAgents.length})
          </Typography>
          <Typography variant="body2" sx={{ maxHeight: 112, overflowY: 'auto', wordBreak: 'break-word' }}>
            {selectedAgents.join(', ')}
          </Typography>
        </Box>
      ) : null}
      <Box sx={{ mt: 1.25 }}>
        <SmallButton
          icon="mdi:phone-in-talk"
          variant="contained"
          label={selected.type === 'call_queue' ? 'Open queue in the switchboard' : 'Call handling in the switchboard'}
          onClick={() => openInSwitchboard(selected)}
          fullWidth
        />
      </Box>
    </Paper>
  ) : null;

  return (
    <PageTemplate
      {...marker}
      title="Call Flow"
      subtitle={domain}
      layout="fill"
      actions={
        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
          <SmallButton
            icon="lucide:clock"
            variant={simDate ? 'contained' : 'outlined'}
            label={simDate ? `Simulating ${formatDateTime(simDate.getTime())}` : 'Time Simulator'}
            disabled={!graph || loading}
            onClick={() => {
              if (!simOpen && !simInput) setSimInput(toLocalInput(new Date()));
              setSimOpen(!simOpen);
            }}
          />
          <SmallButton icon="lucide:refresh-cw" label={loading ? 'Building...' : 'Refresh'} busy={loading} disabled={!domain} onClick={() => void build()} />
          {multiDomain ? <DomainPicker api={api} domain={domain} onPick={pick} /> : null}
        </Stack>
      }
    >
      <Stack spacing={1.5} sx={{ flex: 1, minHeight: 0 }}>
        {simOpen ? (
          <Paper variant="outlined" sx={{ p: 1.5 }}>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} alignItems={{ xs: 'stretch', sm: 'center' }}>
              <TextField
                size="small"
                type="datetime-local"
                label="Simulate date and time"
                value={simInput}
                onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setSimInput(e.target.value)}
                InputLabelProps={{ shrink: true }}
                sx={{ minWidth: 240 }}
              />
              <Typography variant="body2" color="text.secondary" sx={{ flex: 1 }}>
                Greys out the routes that would not be in effect at that moment, from each user's answer-rule time frames.
              </Typography>
              <Stack direction="row" spacing={1}>
                <SmallButton label="Now" variant="text" onClick={() => setSimInput(toLocalInput(new Date()))} />
                <SmallButton
                  label="Clear"
                  onClick={() => {
                    setSimDate(null);
                    setSimInput('');
                    setSimOpen(false);
                  }}
                />
                <SmallButton label="Apply" variant="contained" disabled={!simInput} onClick={applySim} />
              </Stack>
            </Stack>
          </Paper>
        ) : null}

        {error ? (
          <Alert severity="error" title="The call flow could not be built" role="alert">
            {error}
          </Alert>
        ) : null}

        {warnings.length && !loading ? (
          <Alert severity="warning" title={`${error ? 'Details' : 'Partial graph'}: ${warnings.length} ${warnings.length === 1 ? 'warning' : 'warnings'}`}>
            <Box component="ul" sx={{ m: 0, pl: 2.5, maxHeight: 96, overflowY: 'auto' }}>
              {warnings.slice(0, 10).map((w, i) => (
                <li key={i}>{w}</li>
              ))}
              {warnings.length > 10 ? <li>...and {warnings.length - 10} more</li> : null}
            </Box>
          </Alert>
        ) : null}

        {simulation && !loading ? (
          <Alert severity="info" title={`Simulating ${formatDateTime(simDate?.getTime())}`}>
            {simulation.activeTimeframes.length
              ? `Active time frame${simulation.activeTimeframes.length > 1 ? 's' : ''}: ${simulation.activeTimeframes.join(', ')}.`
              : 'No time-frame routing here: every route is always in effect.'}
            {simulation.fallthroughSourceIds.length
              ? ` ${simulation.fallthroughSourceIds.length} ${simulation.fallthroughSourceIds.length === 1 ? 'step falls' : 'steps fall'} through to the lowest-priority rule (no time frame matched).`
              : ''}
          </Alert>
        ) : null}

        {loading ? (
          <Paper variant="outlined" sx={{ p: 2 }} role="status" aria-live="polite">
            <Stack direction="row" spacing={1.5} alignItems="center">
              <Icon name="svg-spinners:ring-resize" size={22} />
              <Box>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                  Reading the phone system for {domain}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  {progress && progress.total
                    ? `${progress.current} of ${progress.total} phone numbers, ${progress.reads} reads so far.`
                    : 'Reading users and phone numbers.'}
                  {pausedFor ? ` Pausing for Horizon's request limit, resuming in ${pausedFor} s.` : ''}
                </Typography>
              </Box>
            </Stack>
          </Paper>
        ) : null}

        {graph && !loading ? (
          graph.nodes.length === 0 ? (
            <Alert severity="info">This domain has no phone numbers routed anywhere yet.</Alert>
          ) : (
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={2} sx={{ flex: 1, minHeight: 0 }}>
              <Paper
                variant="outlined"
                component="nav"
                aria-label="Phone numbers"
                sx={{ width: { xs: '100%', md: 260 }, flexShrink: 0, p: 1.5, display: 'flex', flexDirection: 'column', minHeight: 0, maxHeight: { md: '100%' } }}
              >
                <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1 }}>
                  Phone numbers ({ingress.length})
                </Typography>
                <SearchField size="small" fullWidth value={search} onChange={setSearch} onClear={() => setSearch('')} placeholder="Search" />
                <Box sx={{ mt: 1, pb: 0.5, borderBottom: 1, borderColor: 'divider' }}>
                  <Checkbox
                    size="small"
                    label="Show all"
                    checked={allChecked}
                    onChange={() => setRoots(allChecked ? new Set() : new Set(ingress.map((n) => n.id)))}
                  />
                </Box>
                <Box sx={{ overflowY: 'auto', minHeight: 0, flex: 1, mt: 0.5 }}>
                  {visibleDids.map((n) => (
                    <Box key={n.id}>
                      <Checkbox size="small" label={didLabel(n)} checked={roots.has(n.id)} onChange={() => toggleRoot(n.id)} />
                    </Box>
                  ))}
                  {visibleDids.length === 0 ? (
                    <Typography variant="body2" color="text.secondary" sx={{ py: 1 }}>
                      No matches.
                    </Typography>
                  ) : null}
                </Box>
                {agentsByQueue.size ? (
                  <Box sx={{ mt: 0.5, pt: 0.5, borderTop: 1, borderColor: 'divider' }}>
                    <Checkbox size="small" label="Show queue agents" checked={showAgents} onChange={() => setShowAgents(!showAgents)} />
                  </Box>
                ) : null}
                {builtAt ? (
                  <Typography variant="caption" color="text.secondary" sx={{ mt: 1 }}>
                    Read {formatAgo(builtAt, now)}. Click a user or queue to open it.
                  </Typography>
                ) : null}
              </Paper>
              <CallFlowViewer
                graph={shown ?? graph}
                inactiveEdgeIds={simulation?.inactiveEdgeIds}
                selectable={selectable}
                labels={labels}
                selectedId={selectedId}
                onSelect={setSelectedId}
                overlay={detailsCard}
                fileName={`call-flow-${domain}`}
              />
            </Stack>
          )
        ) : null}
      </Stack>
    </PageTemplate>
  );
}
